// Renders docs/events.md from the schemas, so the document cannot drift from them.
import { EVENT_SCHEMA_VERSIONS, EVENT_TYPES, type EventType } from '../domain/types.ts';
import { EVENT_EXAMPLES } from './examples.ts';
import { LANDING_BATCH_DOCS } from './landing-batch-docs.ts'; import { MACHINE_DISK_EVENT_DOCS } from './machine-disk-schemas.ts'; import { MACHINE_DRAIN_EVENT_DOCS } from './machine-drain-schemas.ts'; import { SANDBOX_HOST_EVENT_DOCS } from './sandbox-host-schemas.ts'; import { TERMINAL_EVENT_DOCS } from './terminal-schemas.ts'; import { CHANGE_KIND_EVENT_DOCS } from './change-kind-schemas.ts'; import { KEPT_WORK_EVENT_DOCS } from './kept-work-schemas.ts'; import { GIVE_BACK_EVENT_DOCS } from './give-back-schemas.ts'; import { ISSUE_DRAFT_EVENT_DOCS } from './issue-draft-schemas.ts'; import { PREEMPTION_EVENT_DOCS } from './preemption-schemas.ts'; import { SKILL_LIBRARY_EVENT_DOCS } from './skill-library-schemas.ts'; import { GITLAB_EVENT_DOCS } from './gitlab-schemas.ts'; import { STEP_SCHEDULE_EVENT_DOCS } from './step-schedule-schemas.ts';
import { exportJsonSchemas } from './export.ts';
import { LEGACY_EVENT_SCHEMAS } from './legacy.ts'; import { WORK_ITEM_EVENT_DOCS } from './work-item-docs.ts'; import { TAGGED_EVENT_DOCS } from './tagged-docs.ts'; import { PUSH_REQUIREMENT_EVENT_DOCS } from './push-requirement-docs.ts'; import { DELIVERY_SETTINGS_EVENT_DOCS } from './delivery-settings-schemas.ts';

export const EVENT_DOCS: Record<EventType, string> = {
  'github_proxy.done': 'The hopper did a GitHub operation a running job asked for (issue #563), with the GitHub connection of the job\'s own user (issue #1380): `op` (`issue.create`, `issue.comment`, `issue.view`, `issue.comments`, `issue.close`, `pr.create`, `pr.view`, `pr.diff`, `pr.commits`, `pr.checks`, `pr.reviews`, `pr.status`, `pr.ready`, `pr.edit`, `pr.close`; issue #1734: a pull request the job opened, or its work item\'s) on `repo`, `number` and `url` where it is; for a read (a repo query, issue #1074), `source`: `github` when GitHub was read for it, `cache` when the hopper\'s repo-query cache answered it, `hopper` when its records answered it (issue #1072, `pr.status`: the Pull requests list and the work-item ledger); for a `pr wait` (issue #1072 part 2, asked as `pr.status`), `wait`: the id of the watch it opened on the job\'s stream while the checks run, `settled` when they had ended, or `none` when the hopper does not follow the pull request — with `--for mergeable` (issue #1210) the watch waits for the next mergeability the hopper sees instead —; `poll` (issue #1210): the job asked the same read this many times in 15 minutes, a poll of hopper state, and the answer told it to wait through the hopper; a repository read or forked (issue #429, `repo.view`, `repo.fork`): its `url`, and for a fork `fork`, the fork made or found in the user\'s account; a failed check\'s log read (issue #993, `check.log`): `number`, its GitHub Actions job, and `url`, its check run (the log itself is never in the event); a repository\'s workflow runs read (issue #2318, `run.list`): `url`, its Actions page, and no `number`; a run and its jobs read (`run.view`): `number`, the run\'s id, and `url`, the run; or the job\'s git push (issue #652, op `git.push`, with the connection of the job\'s own user): `refs`, the refs it changed, and no `number` or `url`; `heads` (issue #2087), the commit each ref moved to, so the reap and the sweep read that work as pushed; `direct` (issue #1806), the refs it moved straight on the repository\'s target branch with direct push on, each a fast-forward. `key` (issue #1607, `issue.create` and `issue.comment`; issue #1959 part 4, `pr.create`): the **resend key** hopper-gh sent with it; the same request sent again with that key is answered from this event, and nothing is done again on GitHub; that answer is recorded as `github_proxy.done` again, with `replayed`. `found` (issue #1959 part 2): the issue, comment or pull request (part 4) was found on GitHub by its **post key**, made by an earlier send of the same key that a hopper killed before it recorded it; nothing was made again. `requestId` names the request (an issue filed this way says it at its end); `machine`, the job\'s machine; `as` (issue #1380), the GitHub login that acted for the job, its own user\'s connected account. Events recorded before issue #1380 carry `own` (the job was the hopper\'s oldest user\'s) and, for another user\'s job, a copy in the oldest user\'s log with `forUser` and `job`.',
  'github_proxy.refused': 'The hopper refused a GitHub operation a running job asked for (issue #563), and told the job `reason`: a request it does not take, a repository it does not work on, a rate limit, or no GitHub connection of the job\'s user; for a git push (issue #652), a push to another repository than the job\'s own (or, with Contribution on, its user\'s fork of it, issue #429), to one its user cannot push to, or to its default or a release branch, a tag or a delete; or a push the **shrink guard** refused (issue #1096): it brings in the default branch and empties or shrinks files the branch\'s own change does not, named in `shrunk` (`path`, its lines `from` — on the base branch, or `against: head` before the push — and `to`). Fields as `github_proxy.done`; `op` and `repo` when the request named them, and a push\'s `refs` when it was read.',
  'github_proxy.failed': 'GitHub failed or refused a GitHub operation the hopper did for a running job (issue #563): `error` is what GitHub answered, as the job was told; for a git push a hopper stopped during (issue #1806, a push kept as a saga), the refs GitHub does not have, recorded by the next hopper. Fields as `github_proxy.done`.', 'github_proxy.sending': 'A running job\'s issue create, comment or pull request create (part 4) with a **resend key** (issue #1607) is on its way to GitHub (issue #1959 part 2): `op` (`issue.create`, `issue.comment`, `pr.create`), `repo`, `number` (the issue a comment goes on) and `key`. Recorded before the call, so a hopper killed before it recorded the answer leaves it: the same key sent again then looks for the issue, comment or pull request (from the same head) on GitHub by its **post key** first, and makes it only when it is not there. Fields as `github_proxy.done`.',
  'job.queued': 'A job was created from a source item; it waits at the queue gate until accepted (`job.accepted`).',
  'job.prioritized': 'The router\'s advice arrived for a job; once per job, whatever its status then.',
  'job.held': 'A Decision held a job and its hold reason changed.',
  'job.approved': 'A human approved a job the router held (e.g. `ask_human`).',
  'job.claimed': 'A Decision assigned a job to a lane.',
  'job.started': 'The executor began running a claimed job.',
  'job.progressed': 'An executor reported progress: a progress message, the job\'s task count (done of total), or both; at most one per job per 500 ms.',
  'job.finished': 'A job ended successfully. `partlyDone` (issue #579): it ended partly done — the URL of its own pull request that ships part of its item ("Part of #N"); the next part runs once that is merged.',
  'job.failed': 'A job ended with an error. `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `tldr` (issue #569): for a long question, what a notification leads with — its TL;DR when written, else the agent\'s own summary; absent for a short one or with the TL;DR off.',
  'job.cancelled': 'A job was cancelled. `reason`: why, as the hopper or its source names it (`cancelled in UI` for a person\'s cancel). `note` (issue #1460): the person\'s own words why, when they gave some; never told to the source.',
  'job.requeued': 'A job went back to the queue (restart recovery, a question answered or closed, or its machine out of reach of the hopper at its start). `reason` is a free string.',
  'job.parked': 'A person, auto-park (issues #650, #2335: `auto`, its question waited on a person a few seconds, or its proposal or research report reached the human stage; `why` says so), or the busy-machine move (issue #1977: `auto`, a job queued to resume on a full machine while another had room; `why` says so) parked a running job or one on a question, a proposal or a research report (issue #501): its lane is free, its pane and agent ended, and its work tree, branch, agent session and open question are kept. `machineId`: the machine it returns to when re-queued. `by`, `via`, `reason` (issue #2167): the person who parked it, the way they did (`ui`, `cli`, `api`), and the reason they gave; a running job that parked it through the `park` skill (`POST /job/park`) is `by` `job <its id>`, `via` `job`. `move` (issue #1892): the hopper parked it to move it off its machine with no person — `signed_out` (issue #1211), `busy_machine` (issue #1977) or `lost_machine` (issue #1569; also a run whose session had no way to the hopper, issue #2427, its `why` says so) — and picks it up elsewhere (`job.unparked`); its work item goes back to queued, not to needs you, and a stop before the pick up leaves the move to its next pass. A parked job never runs, its question never expires, and its proposal or research report is neither reviewed nor decided, until it is re-queued or cancelled.',
  'job.continued': 'An ended job goes on in its own agent session: the job is queued again, pinned to the machine it ran on, and its claim resumes that session in its work tree (`claude --resume`). A person resolved its hand-off with Continue (issue #551), told the failure and the person\'s note: `handoffId`, the hand-off it resolved. Or the failure assessor continued a timed-out job still at work (issue #630), told it timed out while at work: `recordId`, its failure record. Or a person chose Push it on its work not pushed (issue #1010) — a failed, finished or cancelled job —, told to push the work its work tree kept and open the pull request: `keptWork`. Or the failure sweep did so by itself for a finished job (issue #1472, Push it by itself, the failures setting `auto.push`): `keptWork` and `auto`.',
  'job.waiting': 'The job waits on something it named (issue #483): it ended its turn with HOPPER_WAITING. `for`: what it waits for; `until`: how it will know, as it wrote it; `on` (issue #1245): what it waits on, typed — a pull request (`number`, `about`: `checks`, `merge` or `review`), a job, an item, a person\'s question, a `sandbox` or `template` approval, a vault grant, its own command, or an outside event —, from its `on:` line, else read from what it wrote; absent only on a wait from before; `ownCommand` (issue #1037): `until` names its own background command, so it shows as running. Its status is `waiting_on`: no question opens, its lane is free, its pane and agent stay on its machine, and nothing is typed into it. It goes on when its agent goes on by itself (`job.reattached`, reason `the wait ended in the pane`) or a person ends the wait (`job.wait_ended`), or the hopper ends it with an answer the job asked it for (issue #998), or when the event that settles what it waits on comes (issue #1245): the pull request merged or closed, the job ended, the item\'s issue closed, the question answered, closed, dismissed or expired, its vault grant given or denied.',
  'job.own_command_nudged': 'A job waiting on its own background command (issue #1037, `ownCommand` on its wait): its pane showed no background work for the grace (`HOPPER_OWN_COMMAND_GRACE_MS`) and its agent did not go on, so the hopper typed one nudge into its pane: check the command, then go on. `delivered`: false when its pane or agent was gone. Once per wait.',
  'job.wait_polled': 'A job waiting on its own background command (issue #1037) asks the hopper the same read again and again (issue #1210): its command polls hopper state, a pull request or an issue. `on`: what it polls, now its wait\'s `on`, so the UI and the ledger say what it waits on. It stays its own command, so it holds no tending queue. The hopper ends the wait (`job.wait_ended`, by the hopper) an hour after it began, on its next poll, with the last answer. Once per wait.', 'job.own_command_stuck': 'A job waiting on its own background command (issue #1037) did not go on within the grace after its nudge: its wait was flagged stuck (`stuckAt`). Before issue #1694 only; now its wait check ends such a wait.', 'job.waited_items_ended': 'Every item a job\'s own wait names (issue #1508) ended, as a sync of the job\'s source read them: an issue closed, a pull request merged or closed, a workflow run completed. The wait is on an item, or on an outside event whose text names issues, pull requests (`owner/name#N`, `name#N` of the job\'s owner, `issue N`, a link) or workflow runs (`<repo> run N`, `workflow run N`, a link). They may have ended before the wait began. Also at once when one of them does not exist, or the hopper cannot read it (issues #1691, #2066): then `items` holds only those, `state` `not_found`, so the job rewrites its wait. The hopper wakes the job (`job.wait_ended { by: hopper }`). Once per wait; a job woken so that waits again on the same items is not woken for them again until the hopper restarts. `items`: each one\'s URL and `state` (`closed`, `merged`, the run\'s conclusion, or `not_found`).', 'job.waited_pull_request_ended': 'A pull request a job waits on (issue #1433), which no follow of a job recorded the end of, was seen merged or closed without a merge at a sync of the job\'s source: the source reads each pull request a job\'s own wait names. Recorded on each job waiting on it; the hopper wakes them (`job.wait_ended { by: hopper }`), as `job.pull_request_merged` or `job.pull_request_closed` would. `pullRequest`: its URL; `state`: `merged` or `closed`.',
  'job.wait_ended': 'A person ended a job\'s own wait (issue #483), or the hopper did (`by: hopper`, issue #998) when an answer the job asked it for is ready (a skill request: a sandbox, a template, a credential): the job is queued again, pinned to its machine, and its claim tells it in its pane that the thing it waits for has happened, with the person\'s `note`, or the hopper\'s answer, if any. `check` (issue #1694): the hopper\'s wait check ended it — its condition, as a key (`items_ended:…`, `job_ended:<id>`, `question_settled:<id>`, `command_exited`) —; a later wait of the job on the same items is not woken for them again. `comment` (issue #2159): the link of the comment that woke it — a trusted account (the user\'s connected account or a maintainer of the repository) commented on the job\'s issue or its own pull request while it waited; the job is told the comment as untrusted text. `conflicting` (issue #1143): the pull request whose merge conflicts woke it — one a job of the item opened through the hopper, read in a round of every follow while the item\'s newest job waits; the job is told to rebase it and wait again, once for each head of the pull request.', 'job.wait_overdue': 'A job\'s own wait passed the deadline of its wait check (issue #1694): a day after it began, four hours for a wait on its own command. Once per wait. The job stays on its wait, and the hopper checks it each hour after. It is stuck work for a person (Failures, `own_wait`) only when its wait broke (issue #2684): its check cannot test its condition (`brokenAt`), or it was woken for the same items once already. `deadline`: the deadline; `result`: what the last check found.',
  'job.note_added': 'A person, or an agent over the API, sent a note to the job (issue #997, `POST /ui/api/jobs/:id/notes`): `noteId`, its `text`, who (`person`) and how (`via`: `ui`, `api`, `cli`). It is queued on the job (`notes`) until the job\'s session gets it: at the next turn boundary while it runs, in its task as it starts, with the answer as it resumes. A job that waits — on a question, its own wait, a hold, parked — keeps it queued; a new job of its item carries it (`job.note_carried`).',
  'job.note_delivered': 'The job\'s executor typed the queued notes (`noteIds`) into its session (issue #997). `delivery`: `turn` (at a turn boundary while it ran: Claude ready, its turn over, never on a question, a report or a login), `start` (in its task) or `resume` (after the answer it resumed with).',
  'job.note_carried': 'A new job of the job\'s item (run again, rework, I fixed it) took the notes it never delivered (`noteIds`, issue #997): queued on `nextJobId`, `carried` on this job.', 'job.critical_flag_changed': 'A person, or an agent over the API, set (`critical` true) or cleared the job\'s critical flag (issue #2203, `POST /ui/api/jobs/:id/critical`): a job with the flag is a critical job whatever its priority, so the critical job tracker shows it on every page. The lane over the cap stays a rule of the critical priority. `person` and `via` say who acted.', 'job.quarantined': 'A person, or an agent over the API, quarantined the job (issue #655, `POST /ui/api/jobs/:id/quarantine`): its trust stamp is signed `quarantined`, so the decider holds it, and its proxy token opens no door of the hopper (the GitHub proxy, git, the vault, skills, steps, artifacts, its stream) — a running job keeps its pane, but reaches nothing through the hopper. `was`: its trust level before, the level a lift gives back; absent when its stamp did not verify. `reason` `deny:sandbox`: a person\'s second deny at gate 2 in the job quarantined it (part 5: a declined sandbox request), or a deny of a job at `untrusted`; `deny:jev`: Jev\'s deny was the second (part 13). Who (`person`) and how (`via`), or `by` `jev` for Jev\'s deny.', 'job.unquarantined': 'A person, or an agent with a box token, lifted the job\'s quarantine (issue #655, `POST /ui/api/jobs/:id/unquarantine`): its stamp is signed at `level` again — the level it had before its quarantine, or the rules\' level when none was kept. Who (`person`) and how (`via`).', 'job.trust_lowered': 'Jev\'s trust check (issue #655 part 4, the decision point `intake-trust` active) lowered the job\'s trust stamp before it started, `from` its level `to` a lower one: a pick with its reason, or — no answer, not sure, Jev not there — `untrusted` (fail closed). `reason`: the reason id added to the stamp (`jev:touches_ci`, `jev:no_answer`). `by`: `jev`. Or (part 5) a person\'s deny at gate 2 lowered a job one level, `by` `person`, with `reason` `deny:sandbox` (a declined sandbox request), who (`person`) and how (`via`); the second deny in the job quarantines it (`job.quarantined`). Or (part 13) Jev\'s sandbox check denied a sandbox request, `by` `jev`, with `reason` `deny:jev`; it counts with a person\'s denies. Or (part 7) a sync saw the item of a started job edited: its stamp drops to `untrusted`, `by` `edit`, with `reason` `edit:text`; the job goes on with the text it started with, and gate 2 then approves nothing for it with no person until a person approves its trust.', 'intake.stamped': 'The job store signed the job\'s trust stamp from where its work came (issue #655 part 11, design.md "Trust stamps"): at its making (`by` `intake`, or `job` for a job a job made), for a new spec (`respecify`), at the backfill of a job made before stamps (`backfill`), or when a sync judged its origin later (`intake`, or `person` when a quarantine stays). `level` and `reasons`: as on the stamp; `was`: a quarantined job\'s level before it. `from`: the level its stamp verified at before, when it had one. `spec`: the SHA-256 of the spec the stamp covers, as canonical JSON. The MAC is never in it. A job with no stamp (no stamp key, or a parent whose stamp does not verify) has none.', 'job.trust_approved': 'A person, or an agent with a box token, approved the trust of a job Jev\'s trust check, a deny at gate 2 or an edit of its item lowered, or of a job with no item held below approved (issue #655 parts 4, 5 and 7, issue #1974, `POST /ui/api/jobs/:id/approve-trust`): its stamp is signed `approved`, `from` the level it had. Who (`person`) and how (`via`).',
  'job.unparked': 'A person, or the signed-out move (issue #1211), re-queued a parked job (issue #501). `to` `queued`: it waits, pinned to its machine, and its claim resumes its agent session there (`claude --resume`), with the answer kept while it was parked, if any. `to` `waiting_answer`: its question is still open; the answer resumes it, and the human timeout starts again. `by`, `via` (issue #2167): the person who picked it up and the way (`ui`, `cli`, `api`), or `job <its id>` and `job` for a running job that picked up a proposal or research report it parked through the `park` skill. `elsewhere` (issue #921): picked up to resume on another machine from its checkpoint: it is not pinned to its machine, and its claim rebuilds its work tree from the checkpoint on the machine it gets and resumes its agent session there. The signed-out move and the busy-machine move (issue #1977) re-queue with `elsewhere` too: from the checkpoint, or as a new start when the agent never got its task.',
  'job.checkpointed': 'A checkpoint of a job at work, or of one just parked, or for a fresh read of its transcript (issue #1169), was taken and kept (issue #921): its agent session and its work not pushed, read on `machineId`, scrubbed of secrets. `bytes`: its size compressed. `session`: whether it holds the agent session (without it, the job cannot resume elsewhere). `commits`: the commits not pushed then. Only the latest checkpoint of a job is kept.',
  'job.reattached': 'The executor watches a job\'s live external work again (the herdr pane and Claude) without sending anything. `reason` `daemon restart`: restart recovery kept a running job running on its lane. `reason` `answered in the pane`: the owner typed the answer into a waiting job\'s pane; the job runs again on a lane. `reason` `link restored` (issue #752): the machine\'s link is back after `job.link_lost` and the job\'s pane is alive; it goes on from its saved turn. `reason` `its hopper stopped` (issue #1662): another hopper on the same database took over a running job whose lease ended.',
  'job.link_lost': 'The link to the running job\'s machine (`machine`) dropped while it was watched (issue #752). The job is held: it stays `running` on its lane, and the hopper asks every second whether its pane is alive again. `since`: when the link was found down. `failsAt`: when the job fails if the link is not back (the link grace). It goes on with `job.reattached` (reason `link restored`), or fails with "machine <id> did not reconnect within <n> s" and its cleanup deferred.',
  'job.reprioritized': 'A source re-sorted a waiting job.',
  'job.respecified': 'A sync worked out a job that has not started from the config as it is now (issue #375), and its executor, model, work tree, default work tree, machine pin or routing rule changed. `from` and `to` are what the source and routing rules gave it; a part changed on the job by hand keeps the hand value, so the spec can differ from `to`.',
  'lane.opened': 'A Decision opened a lane.',
  'lane.closed': 'A lane closed (decision reason, `drained`, or `daemon restart`).', 'lane.unhealthy': 'A lane is unhealthy (issue #2234): its last `failures` starts failed with the same start error, `error` the last; it takes no new job until `until`.',
  'decision.made': 'The engine recorded a Decision.',
  'question.asked': 'A running job paused on a question. `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `text`: the question as the agent wrote it, Markdown source (issue #569).',
  'question.escalated': 'A question entered a stage — `target` is an escalation level\'s instance name, or `human` — or the human was re-notified. `reason` says why it climbed: the reply or the failure of the level below, or a risk rule hit. `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `holds` (issue #679): every hold on the level\'s answer that sent it, strongest first — `guard` (`by` `risk` or `guard`, the `guards` by name), `high_priority`, `auto_answer_off`, `low_confidence` (with the `confidence` and the `threshold`). A risk hold the Decider made (issue #679) carries `decider` in place of `guards`: its `risk`, `categories`, `confidence` and `threshold`, or the `error` it failed with.',
  'question.escalated_to_human': 'A question reached the human stage: every level escalated, there are no levels, or a risk rule hit. Once per question, right after its `question.escalated` with `target` `human`; never on a level hop or a re-notification. Subscribe to it to hear only the questions the owner must answer: the Grok Bot routine webhook listens to it and to no `question.escalated` (issue #481). `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `holds` (issue #679): every hold on the level\'s answer that sent it, strongest first — `guard` (`by` `risk` or `guard`, the `guards` by name), `high_priority`, `auto_answer_off`, `low_confidence` (with the `confidence` and the `threshold`). A risk hold the Decider made (issue #679) carries `decider` in place of `guards`: its `risk`, `categories`, `confidence` and `threshold`, or the `error` it failed with.',
  'question.answered': 'An answer was accepted: an escalation level\'s (`by` = the level instance; `auto: true` with its `confidence`: it went into the job with no person, issue #632), or the human\'s (`via: "pane"` when they typed it into the job\'s pane: the job already runs again, nothing is typed for them).',
  'question.corrected': 'A person corrected an escalation level\'s auto-answer (issue #632): `was` is the level\'s answer that went into the job, `answer` the correction. The job gets the correction with its next answer or resume; the agreement stats count it against the level\'s auto-answers.',
  'question.closed': 'The owner closed an open question without answering (UI Close). The job resumes with `answer`, the fixed close text, typed in; any escalation level call in flight is aborted.',
  'question.dismissed': 'The owner dismissed an open question (UI Dismiss): it needs no action any more. Nothing is typed into the job; a job still waiting on it is cancelled (`job.cancelled`, reason `question dismissed`); any escalation level call in flight is aborted.',
  'question.expired': 'The human stage timed out and the job fails.',
  'question.lapsed': 'Nobody answered a dialog in time: the agent denied it by itself when its countdown ran out (Claude Code\'s auto-deny), and the job went on (`job.reattached`, reason `the dialog lapsed`). `lapsesAt` is when the countdown ended. Not an answer: nothing is typed, and no stage answered; any escalation level call in flight is aborted.', 'question.cancelled': 'An open question was cancelled: its job ended or is gone (at a restart, or on the sweep), so nothing waits on it any more. Nothing is typed into the job; any escalation level call in flight is aborted. The UI drops it from the open questions and the Needs you count (issue #1457).',
  'update.available': 'A check found a newer target on the update channel than the installed commit (once per target). `ref` is the branch of the channel; `changes` counts its commits not installed (an operator detail; the UI shows the bullets of WHATS-NEW.md instead). `pullRequest` (issue #652): the number of the pull request the target is the merge of, whose checks passed; only such a target is announced, a held one never.',
  'update.started': 'Applying an update began (UI, or auto-update): the target is built beside the running install. Running jobs keep running.',
  'update.applied': 'The first boot on an applied update: the install now runs `to`. Recovery reattached what was running.',
  'update.failed': 'Applying an update failed (fetch, build, the new build not loading, or the swap) and the install is unchanged — or a boot after an update is not on the applied commit.', 'install.seen': 'An update check saw the install run `commit`, built from `branch`, for the first time (issue #2775 part 10): at the boot after an update, and for an image too. `from`: the commit seen before it, if one was. `mergeCommits`: the merge commits `commit` carries beyond `from` (at most 500, newest first), so a job\'s kept delivery track finds its batch run\'s merge among them and its production step ends.',
  'plugin.installed': 'A plugin was installed from the plugin store into the plugin dir (UI Install or Update), at the store\'s commit `commit`. A plugin new to this process is loaded at once; one installed again runs its new code after a restart.',
  'plugin.removed': 'A store install was removed from the plugin dir (UI Remove). Nothing in the plugins config named it.',
  'job.accepted': 'A job passed the queue gate and may run: `by` `pre-sort` (the gate auto-accepts, or the user took the pre-sort with Accept pre-sort), or `user` (moved into the user order).',
  'job.rejected': 'A waiting job was turned away at the queue gate: it ends `rejected`, is kept, and never runs. `by` `user` (UI Reject, with the reason the user gave, else `rejected by the user`) or `pre-sort` (the queue sorter rejected it); `reason` is also the job\'s `error`. Its source is told; on GitHub the issue is left as it is — no label, no comment, never closed — and is not taken again until it is assigned to the account again or run again (issue #387).',
  'queue.ordered': 'The user ordered the queue: `jobIds`, first to last, run before every job not in it.',
  'job.claimed_by_operator': 'An operator claimed the waiting job as operator-led (issue #318): the work is done by hand — at a terminal, or in an IDE the hopper has no pane in — not by an executor. The job holds no lane and is never run; it is finished when its closing pull request reaches the completion, as any job is, and cancelled as any job is.',
  'job.rerun': 'The user (`by: "user"`), or the failure assessor (`by: "assessor"`: a retry, a redirect, a held job released — issue #509), or the hopper\'s tending of a waiting pull request (`by: "tending"`: merge conflicts or failing checks, issue #736; `job.pull_request_tended` follows), or the item reconciler (`by: "reconciler"`: its pull request closed without a merge on GitHub, the first time in a row, issue #1891), asked for an ended job\'s item to run again (UI Run again, a re-run): its source gave the item back (on GitHub: a closed issue reopened, the end labels gone) and the new job was queued in the same step, its `job.queued` just before this event and its `rerunOf` this job; `nextJobId`: the new job (issue #2775 part 9; older events name none). The ended job is kept as it ended; a failed one is no longer a locked entry. A person\'s run again from Failures — a failure\'s Retry, a hand-off\'s I fixed it, or Continue in a new job — names who: `person`, and the way, `via` `ui` or `cli` (issue #623).',
  'job.rework_requested': 'A person sent a finished job\'s open pull request back for rework (issue #724: the card in Pull requests, `hopper job rework`, or `POST /ui/api/jobs/:id/rework`), with notes: the pull request became a draft and stays open on its branch, the job no longer follows it, and the new job of its item (`nextJobId`, its `rerunOf` this job) reworks it, told the notes. That job is done only when it pushed to the pull request after the rework and marked it ready. `person` and `via` (`ui`, `cli`): who acted and the way.',
  'job.dismissed': 'A locked entry was dismissed (issue #355): the failed job stays failed and leaves the queue. It can still be run again. Its issue keeps `hopper:failed`. `by`: `user` (a person), or, by itself, nothing waits on it any more (issue #1123): `superseded` (a newer job of its item took its place) or `item_closed` (its item is closed at its source, done or dropped). Only a person\'s dismissal opens a hand-off.',
  'job.unassigned': 'A started job\'s issue is no longer assigned to `assignee`, the account it was taken for (issue #387). The job runs on, flagged (`sourceState.sync.unassignedAt`); the user decides whether to stop it. A waiting job is cancelled `unassigned` instead. Recorded once per flag.',
  'job.reassigned': 'A flagged job\'s issue is assigned to `assignee` again (issue #387): the flag is cleared.',
  'job.work_kept': 'The reap at the job\'s end (issue #401), or a later sweep (issue #410), kept its scratch dir and its job worktrees (issue #1188: in its work tree\'s `.worktrees`): each of `paths` is a repository there holding uncommitted or unpushed work. `reasons` (issue #2494; absent from a client older than that) says, for each path, why: `dirty` (a change not committed), `stash` (a stash), `unpushed` (commits no remote has). Nothing in it was removed; the job\'s processes were still stopped. The sweep tries again on each pass, and removes it once the work is pushed (`job.work_removed`).',
  'job.work_removed': 'The sweep (issue #410), or the job\'s next reap, removed the scratch dir a reap had kept (`job.work_kept`): its work is now committed and pushed. `paths` is the scratch dir removed. With `discarded` (issue #1010), a person discarded the kept work in Failures, Work not pushed: the scratch dir was removed whatever it held; `person` and `via` say who and the way. With `discarded` and `reason` (issue #1187), the sweep discarded it with no person, as nobody waits on it: `merged` (its item is done, issue #1105), `superseded` (a newer job of its item finished with nothing kept), `proposal` or `research` (it finished a proposal or a research report, never work to push), `pushed` (issue #2087: the hopper pushed each commit of it for the job). With `gone` (issue #1120), the sweep found the scratch dir and its job worktree no longer on the job\'s machine (removed by hand, or by a cleanup outside the hopper): the record is resolved, and nothing was removed.',
  'job.cleanup_deferred': 'The job ended, but its cleanup could not reach its machine (`error`), so its pane and agent may still run there. Recorded once per deferral; the cleanup is tried again on every tick, and a waiting job of the same item is held until it goes through.',
  'job.cleaned_up': 'A deferred cleanup went through: the job\'s pane is closed and its work reaped. `deferredAt` is when it was deferred. `by: "user"`: the user marked it cleaned up (they closed the pane by hand, or its machine is gone for good), and it is no longer tried. `dueAt` (issue #1570): a stop of the hopper came between the job\'s end and its cleanup, which the next start did from its record; `dueAt` is when the record was written, at the job\'s end. Recorded only for a deferred cleanup, or one done after a stop.',
  'source.stalled': 'A job source has been in error since `since` for longer than the stall threshold (30 minutes): nothing new is pulled from it. Recorded once per run of failures; `error` is its last error. The notifiers send it.',
  'connected_account.expired': 'The sign-in of the user\'s connected account ended: GitHub refused its refresh token itself and no newer pair was stored (revoked, or the app\'s authorization removed), or the token expired with nothing to renew it (`reason`). A renewal that failed for a reason that may pass (GitHub not answering, a 5xx, a rate limit) never ends it. The account reads as expired until connected again; its source pauses and asks to connect again; nothing reads GitHub in its place. Recorded once. The notifiers send it.',
  'connected_account.renewed': 'The renewer kept a new token for the user\'s connected account (issue #647): when the new one expires (`expiresAt`; absent: it does not). Never a token. Running jobs are handed the new token on their machines at once.',
  'connected_account.renewal_failed': 'A renewal of the user\'s connected account failed (issue #647): GitHub\'s OAuth error (`code`: `bad_refresh_token`, `incorrect_client_credentials`, …), `http_<status>` when GitHub answered with no OAuth error, `renewal_blocked` when this hopper cannot renew it as it is set up, `no_answer` when GitHub did not answer. Never a token. Recorded at each failed try; `connected_account.expired` follows when the failure ends the connection.',
  'ui_session.ended': 'A UI session of the user\'s ended (issue #439), with the realm it signed in with and why (`reason`): `expired-idle` (no request for the idle timeout), `expired-absolute` (its maximum passed), `refresh-refused` (a gateway realm\'s session whose forwarded token no longer checks out), `provider-unreachable` (that token\'s issuer stayed out of reach past the grace period), `realm-changed` (the sign-in config changed: its realm gone or off, or no rule grants it a role), `connection-ended` (signed in with GitHub, and the user\'s GitHub connection ended: `connected_account.expired`; issue #513 — recorded only before issue #1380, since then a connection that ends ends no session) or `logout`. The session lengths are Settings → Sign-in\'s.',
  'source.claim_released': 'A `hopper:claimed` label (and its `hopper:held-by:<id>` holder label) was removed from an item no job here holds (issue #440). `by: "hopper"`: the claim was this user\'s own, its job gone — the item is taken again; `by: "migration"`: the intake migration released a claim written before claims named their holder, which no user of this hopper has a job for; `by: "user"`: released from Sources. `reason` says which.',
  'source.intake_migrated': 'A job source was moved to the current intake rules, once (issue #440). `changes` lists every item it changed or found needing the user: claims it released, and labelled issues not assigned to the user. Sources shows the same list.',
  'source.request_approved': 'A person approved a request card (issue #652): an issue not of a trusted origin — `actors` says who wrote, labelled and assigned it (on GitLab also who edited its title or description, `edited`, issue #1642), and whether each is a trusted actor —, whose title and body hash as `hash`. Its text is the item\'s snapshot (`approved`): the next sync takes it, and its job runs that text. `person` and `via`: who approved it. Never the text.',
  'source.request_auto_approved': 'The hopper approved a request card a rule of the user\'s auto-approval matched (issue #1268), as a person\'s approval does: its text is the item\'s snapshot (`approved`), the next sync takes it, and its job runs that text. `rule`: `reopened` (a trusted actor or a listed app reopened the issue after its job was done), `author` (a trusted actor wrote it), `app` (a listed app or bot wrote it) or `high-label` (a trusted actor or a listed app added `hopper:high`); `actor`: who did that act. A GitLab card (issue #1642) by `author` or `high-label` only. `actors`: who wrote, labelled and assigned it, as on `source.request_approved`. Never the text.', 'source.request_opened': 'A new request card (issue #798): an open labelled issue assigned to the user that is not of a trusted origin, so it is no job until a person approves it (issue #652). `why` says why it is not trusted; `hash` is the hash of its title and body. Recorded once per item and text: an edit to its title or body opens it again. Never the text. It shows in Not taken, with Approve; the Grok Bot routine notifier posts it.',
  'source.request_declined': 'A person declined a request card (issue #1035): an issue not of a trusted origin, whose title and body hash as `hash`. It makes no job and leaves the request cards waiting in Intake. `choice` (issue #1710): `close`, the hopper closes the issue as not planned and takes off the source\'s label, its priority labels and `hopper:done`; `open`, the issue stays open and loses the source\'s label. Either way one comment on the issue says what the hopper did; these writes are rows in the GitHub outbox, and `source.request_decline_written` follows once GitHub took them. Then the issue comes back only when a person adds the label again. With no `choice` (before issue #1710, or a GitLab card), nothing is written, and an edit to its title or body makes it a request card again. `person` and `via`: who declined it. Never the text.', 'source.request_decline_written': 'GitHub took the writes of a person\'s decline (issue #1710): the labels came off, the comment was posted and, for `choice` `close`, the issue was closed as not planned. From now on the issue\'s labels and state are the record of the decline, the same on every hopper.',
  'source.delivery_received': 'GitHub sent the hopper a **GitHub delivery** (issue #1079): `event` (`issues`) and `action` (`opened`, `labeled`, `assigned`, …) on `repo`, issue `number`; `delivery` is GitHub\'s id of it (`X-GitHub-Delivery`). Recorded in the log of each user whose job sources `sources` take `repo` as a job repository: each lists it again at a sync a few seconds later, not after the intake sync interval. Not recorded for a repository no job source of the user takes.',
  'source.backburner_lifted': 'A person took an item off the backburner from Not taken or Sources (issue #798): its `hopper:backburner` label was removed. The source syncs at once, so it is taken when nothing else keeps it out.', 'source.issue_taken_in': 'A person took an issue into Intake from the Pull requests view\'s Not tracked list (issue #1176): an untracked pull request (`pullRequest`) closes it, and it was no work item. The issue (`key`) got the source\'s label and was assigned to the connected account (`assignee`), as Assign to me assigns. The source syncs at once, and Intake lists the issue: a request card when the label is not a trusted actor\'s.',
  'job.origin_judged': 'A job queued before origins were judged (issue #652, the backfill: tenant migration 39) got its item\'s origin: its issue is of a trusted origin (`trusted`), or a person approved its request card (`approved`). Its hold for its origin ends. Until then the job does not start.', 'intake.decline_changed': 'An admin changed the choice Decline offers first in Settings → Intake (issue #1710): `request` for a request card, `reopened` for a reopened card, each `close` or `open`. `from` and `to`, `by` who changed it.',
  'intake.auto_approval_changed': 'An admin changed the user\'s auto-approval in Settings → Intake (issue #1268): `on`, whether the hopper approves the request cards a rule matches, and `apps`, the apps and bots trusted to act for the user. `from` and `to`, `by` who changed it.', 'intake.actors_changed': 'The user\'s trusted actors changed in Settings → Intake (issue #652): the GitHub logins whose issues, labels and assignments start the user\'s jobs. `from` and `to` the logins named (empty: the connected login only), `by` who changed them.', 'intake.strictness_changed': 'An admin changed the intake strictness in Settings → Intake (issue #655, brake 1): the trust level a job\'s stamp needs before the job starts, `default`, by job source (`sources`) and by repository (`repos`, `owner/name` lowercased). `open` needs `screened`, `standard` `approved`, `strict` `trusted`, `closed` `owner`. It applies at the next Decision. `from` and `to`, `by` who changed it.',
  'source.issues_assigned': 'The user assigned these labelled items (`keys`) to their connected account from Sources (issue #440): the next sync takes them. `assignee` is the account. Recorded once GitHub took the assignment, after the action answered, one event per item (issue #1194).',
  'auth.pending': 'A job or run waits on a login (issue #476): a CLI shows a device code to enter at a URL. Kind `paste_code` (issue #1128): a tool sign-in a person started on the machine (`machineId`), with no job, `run` `sign-in`; the person pastes the code its page shows. It goes to the logins, never to the questions or an escalation level. `run` is the executor or escalation level that waits; `questionId` when it is an escalation level\'s run for that question. Again, with the same `loginId` and `renewed: true`, when the same tool shows a new code for the same job: a login is updated, never duplicated. The URL and the code are never in an event, a log or a webhook: only a UI session of the user reads them, from `GET /api/logins`. `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `holds` (issue #679): every hold on the level\'s answer that sent it, strongest first — `guard` (`by` `risk` or `guard`, the `guards` by name), `high_priority`, `auto_answer_off`, `low_confidence` (with the `confidence` and the `threshold`). A risk hold the Decider made (issue #679) carries `decider` in place of `guards`: its `risk`, `categories`, `confidence` and `threshold`, or the `error` it failed with. `host` (issue #698): the host of the URL to open — what asks —, never its path or query. The Grok Bot routine notifier posts it (issue #698).',
  'auth.completed': 'The machine went on after the login: the tool proceeded (or ended), and the job works again. `by: requester` (issue #1110): the job that asked for the login said it went through (`sh "$HOPPER_LOGIN" completed`, `POST /job/login`); it may complete a login that had failed.',
  'auth.expired': 'The login\'s code ran out (`expiresAt`) before the machine went on. By the logins setting, the job is then asked for a new code by itself (`renewing: true`, the default since issue #1016), holds for a new code a person asks for, or fails with the reason. The Grok Bot routine notifier posts it.',
  'auth.cancelled': 'The user cancelled the login. A herdr job is told to stop waiting for it and to go on without it, or to fail.',
  'auth.failed': 'What waited on the login ended first (`reason`: the job ended, the run ended with an error), or, `by: requester` (issue #1110), the job that asked for it said it did not go through, and why.', 'auth.reopened': 'The job that asked for a login said a completed (or dismissed) login does not work after all (issue #1110, `sh "$HOPPER_LOGIN" failed`): the login waits on the user again, with the `reason`, until the job reports a new code (`auth.pending`, `renewed: true`).', 'auth.dismissed': 'A person put an open login away (issue #1110, `POST /ui/api/logins/:id/dismiss`), whatever its job does: it leaves the active list, and the run that waited on it stops waiting.',
  'job.assessed': 'The failure assessor judged a failed job (issue #509): its error normalised to a `signature`, matched to a known cause (`causeId`), its `class` (`transient`, `shared` or `job`), its `decision` — `retry` (runs again at `retryAt`, within the retry limit), `hold` or `redirect` (grouped into the problem `problemId`; a redirected job runs again at once, kept off the problem\'s machine), or `person` — with its `reasons` and a `summary` for a person. `attempt`: its run in its chain of retries. `auto: false`: that decision\'s automatic action is off in the failures settings, so it waits for a person. Once per failed job. `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `holds` (issue #679): every hold on the level\'s answer that sent it, strongest first — `guard` (`by` `risk` or `guard`, the `guards` by name), `high_priority`, `auto_answer_off`, `low_confidence` (with the `confidence` and the `threshold`). A risk hold the Decider made (issue #679) carries `decider` in place of `guards`: its `risk`, `categories`, `confidence` and `threshold`, or the `error` it failed with.',
  'failure.grouped': 'A failed job was grouped into a problem (issue #509): one shared cause, shown once with the jobs it hit. `opened: true` for the job that opened it. `general: true`: no known cause, flagged because the same signature failed enough items within the grouping window. While it is open, a new job its `scope` covers (a machine, an executor on it, or every machine) is held — or placed on another machine — with the reason `held by problem: <title>`. `affected`: its jobs so far.',
  'failure.resolved': 'A problem was resolved (issue #509): by a person (`by: "user"`), or by its check (`by: "check"`: the machine is reachable again, or its disk has room again; for a hopper bug a job reported, issue #1147, the fix landed: the issue of its report closed as completed, and the build of this hopper newer than that close). Its jobs held for it run again through the normal queue (`released` of them), and new jobs are no longer held for it. A person\'s resolution (issue #623) says who (`person`, and the way, `via` `ui` or `cli`) and keeps their `note`, if any.',
  'failure.released': 'A person released a problem\'s held jobs (issue #623): `released` of them run again now through the normal queue, each with its own `job.rerun` by the assessor. The problem stays open. `person`: who; `via`: the way, `ui` or `cli`.',
  'handoff.opened': 'A failed job was handed off to a person (issue #516): automatic handling has ended for it, and it waits in Failures, Needs a person, until a person resolves it (issue #551) or its item runs again — never dropped by age or a restart. `reason`: `retry_limit` (its retries used up), `person` (a job-specific failure), `auto_off` (its decision\'s automatic action is off in the failures settings), `not_retried` (a run again the assessor decided was refused), or `dismissed` (its locked entry dismissed with nothing else to end it). `summary` and `recordId`: its assessment. `notify: false`: the failures setting says not to tell anyone, and no webhook delivers it. Once per hand-off. `priority`, `high` (issue #535): the job\'s live priority, and whether it is at or above the high-priority threshold. `holds` (issue #679): every hold on the level\'s answer that sent it, strongest first — `guard` (`by` `risk` or `guard`, the `guards` by name), `high_priority`, `auto_answer_off`, `low_confidence` (with the `confidence` and the `threshold`). A risk hold the Decider made (issue #679) carries `decider` in place of `guards`: its `risk`, `categories`, `confidence` and `threshold`, or the `error` it failed with.',
  'handoff.closed': 'A hand-off ended (issue #516): `end` `run_again` (its item ran again, from Needs a person, the Queue, the failure\'s Retry or its source; `nextJobId` the new job), `continued` (a person resolved it with Continue and its job goes on in its own agent session; `nextJobId` that same job, issue #551), `done_by_hand` (a person did the work themselves; its job ends finished), `wont_do` (a person decided it is not to be done, or no real failure; its locked entry dismissed), `cleared` (closed by the build before #551: a person acknowledged it, its locked entry dismissed), `finished` (its job ended finished: its issue closed as complete); or, found stale by the sweep or at start (issue #529), `superseded` (a newer job of its item exists; `nextJobId` it), `item_closed` (its item is closed at its source), `job_gone` (its job is gone) or `resumed` (its job is live again — a Continue, Push it or a resume took it back to the queue —, issue #1777). A person\'s resolution names who: `person`, and the way, `via` `ui` or `cli` (issue #623).',
  'handoff.checked': 'What an open hand-off\'s work shows at its job\'s source changed (issue #621): the failure assessor asks the source, at once for a new hand-off and then every 10 minutes, for the job\'s item and the pull requests the job opened or pushed to, and keeps the answer on the hand-off for its card. `item`: `open`, `done` (closed as completed), `closed` (closed any other way) or `gone`. `pullRequests`: how many pull requests of the job\'s it found. `shipped`: a pull request of the job\'s merged, or its item closed as completed — then the hand-off closes (`handoff.closed`, `end: "finished"`) and the job ends finished (`job.finished`), its source told so in place of the failure. Only when the answer changed.',
  'priority_lanes.changed': 'The priority lanes changed (issue #535): `from` and `to` the lanes high-priority jobs get first, best first. `by`: `reliability` (the hopper measured its lanes again and a lane became more reliable by more than the margin, or one dropped out), `manual` (an admin chose them), `settings` (a settings change, such as the count).',
  'priority_lanes.settings_changed': 'An admin saved the priority lane settings (issue #535): `from` and `to` the high-priority threshold, the count of priority lanes, what a priority lane does while no high-priority job waits (`keep-free` or `share`), the window and the minimum runs lane reliability is measured over, and the lanes an admin chose (`manual`; absent: by reliability).',
  'usage.limits_changed': 'The usage limits were set in the UI (issue #522): `from` the soft and hard limits the decider used, `to` the ones it uses from now on. Each is a fraction of a usage budget, from 0 to 1. `softLanes` (issue #2091; absent on events before it): the lanes a machine keeps from the soft limit to the hard limit.',
  'proposal.asked': 'A person asked a job that has not started for a proposal (issue #537): when it starts, its agent is told to write one instead of doing the work. A job from an item labelled `hopper:proposal` is asked from the start, with no event. `by` `user`: a person asked; `jev`: Jev\'s kind check (issue #655, the decision point `intake-kind`, active) asked a work job from a job source before its first start.',
  'proposal.submitted': 'A job came back with a proposal (issue #537): its agent ended with HOPPER_PROPOSAL instead of doing the work. Version 1, or the next version of one sent back. The job waits on it. v2 (issue #651): a proposal is a set of paths; `tldr`: its TL;DR, Markdown source (issue #569), `paths`: how many paths it has, `missing`: the parts it left out (TL;DR, Problem, Paths, Recommended, Context). v1: `goal`, its Goal part.',
  'proposal.escalated': 'A proposal entered a stage of its review (issue #537): `target` is the reviewer level (an escalation level named in the proposal settings) or `human`, and `reason` why it climbed. v2 (issue #651): `tldr`, its TL;DR; v1: `goal`.',
  'proposal.escalated_to_human': 'A proposal reached a person (issue #537): every reviewer level passed it up, there are none, or they asked for changes more often than the settings allow. Once per version. `tldr` (issue #569): its TL;DR part, the agent\'s headline (issue #651), or for a proposal written before paths, its summary.',
  'proposal.reviewed': 'A reviewer level gave its verdict on a proposal (issue #537): `approve`, `request_changes` or `escalate`, with its `notes`. `error`: the review failed, which escalates. `paths` (issue #651): the paths the level added to the proposal and those it found not viable, by id, before a person sees them.',
  'proposal.revision_requested': 'A proposal was sent back to its job (issue #537), by a reviewer level or a person (`stage`; `by` names the person): `decision` `request_changes` (a level, or the structural pre-check: `notes` is what to change), `more_paths` (a person asks for more paths, issue #651: the job keeps its paths and their numbers and adds new ones; `notes` is optional) or `steer` (a person sends a note back: `notes`). A selection the person made so far is kept on the proposal for the next version. The job is re-queued with it and writes the next version.',
  'proposal.accepted': 'A proposal was signed off as accepted (issue #537), by a person (`stage: "human"`, `by` who), by the top reviewer level where the proposal settings let it, or by the hopper itself (`stage: "hopper"`, issues #1059, #1174: one recommended path, or each of a recommended combination, and no rule needs a person). `selected` (issue #651): the paths the person continues with, each with its note (the top level continues with the recommended paths); none on a proposal of zero paths. Its job ends finished, with the decision as its result; each selected path continues as a follow-on job (`proposal.followed_on`).',
  'proposal.followed_on': 'An accepted proposal\'s selected paths each continue as a follow-on job (issue #651): `followOns` names each path and its new job, queued (`job.queued` with `followOn`) and accepted at once, with the parent job\'s spec and priority, told its path and the person\'s note. On the parent job\'s timeline.',
  'proposal.rejected': 'A person rejected a proposal (issue #537), with why (`notes`). Its job ends finished, with the decision as its result.',
  'proposal.cancelled': 'A proposal waiting on a decision was cancelled because its job ended or is gone (issue #537).',
  'research.asked': 'A person asked a job that has not started to research (issue #543): when it starts, its agent is told to research and write a research report instead of doing the work. A job from an item labelled `hopper:research`, or with a Research heading in its body, is asked from the start, with no event. `by` `user`: a person asked; `jev`: Jev\'s kind check (issue #655, the decision point `intake-kind`, active) asked a work job from a job source before its first start.',
  'research.submitted': 'A job came back with a research report (issue #543): its agent ended with HOPPER_RESEARCH_REPORT instead of doing the work. Round 1 (`version`), or the next round after a dig deeper or a steer. The job waits on it, keeping its session. `question`: its Question part, Markdown source (issue #569); `missing`: the parts it left out.',
  'research.escalated': 'A research report entered a stage of its review (issue #543): `target` is the reviewer level (an escalation level named in the research settings) or `human`, and `reason` why it climbed.',
  'research.escalated_to_human': 'A research report reached a person (issue #543): every reviewer level passed it up, there are none (the default), or they asked for changes more often than the settings allow. Once per round. `tldr` (issue #569): for a long one, its TL;DR when written, else the agent\'s own summary.',
  'research.reviewed': 'A reviewer level gave its verdict on a research report (issue #543): `approve`, `request_changes` or `escalate`, with its `notes`. `error`: the review failed, which escalates.',
  'research.revision_requested': 'A research report was sent back for another round (issue #543): `decision` `dig_deeper` (a person: deeper on the whole report, or on the open threads `notes` names), `steer` (a person: `notes` is the new direction) or `request_changes` (a reviewer level). The job is re-queued with it, in the same session, and its next report is the next round.',
  'research.accepted': 'A research report was accepted (issue #543), by a person (`stage: "human"`, `by` who) or by the top reviewer level where the research settings let it. A job that also asks for a proposal is re-queued to write it, in the same session; a job that was not asked for research (its own item asked for it within wider work) is re-queued in the same session, told it was accepted, and goes on with the rest of its work or ends done by itself (issue #538); any other ends finished, with the decision as its result.',
  'research.cancelled': 'A research report waiting on a decision was cancelled because its job ended or is gone (issue #543).',
  'machine.discovered': 'A machine\'s discovery (issue #542) found something new: the first one, or tools, AWS identities, kubectl contexts or credential sources that came (`changes.added`) or went (`changes.removed`), or a level that moved (`changes.level`). `level`: its blast radius, rated with the rules then. Names only: never a secret.',
  'machine.discovery_failed': 'A machine\'s discovery (issue #542) did not finish: `error` says why. The facts of the one before are kept, and so is its rating.',
  'machine.radius_grew': 'A discovery raised a machine\'s blast radius (issue #542), `from` one level `to` a higher one. The machine is flagged on Machines until its level drops.',
  'machine.actor_mismatch': 'An actor machine\'s rating (issue #542) is not the level declared for it: `expected` the declared level, `found` the one its discovery gave.',
  'machine.memory_low': 'A machine\'s free memory stayed under the memory alert\'s threshold (`thresholdBytes`) for the minutes set, `since` it went under (issue #868). `of`: `windows` for a WSL machine, whose free memory is Windows\' own (`freeBytes` of `totalBytes`), read through WSL interop; `machine` for any other, its memory available. Once per stretch under.',
  'hopper.event_loop_stalled': 'The hopper\'s event loop was held for `ms` (issue #1154): for that long no request was answered and no machine\'s link was served. `during`: the routes of the requests in flight, never their URLs. `store`: the store calls in it (all of them, issue #1383), `ms` in all and the statements that held it longest (`what`: the verb and table, never a value). `processes` (issue #2367): the processes the hopper started in it, each of which holds the loop while it forks: `count` in all and the programs started most (`what`: the program\'s file name, never its path or arguments); absent when none. `held` (issue #1383): where the loop ran while it was held, read by a thread of its own each 5 s of it, at most three reads: `afterMs` into the stall, and the top `frames` (`function (file:line)`, the file in the hopper\'s tree only); absent when no read was taken. `memory`: the process\'s resident size and JavaScript heap in use when it ended, in MiB. `skipped`: the stalls since the last one raised, which are logged only: at most one is raised a minute. An instance event: in every user\'s log.', 'machine.memory_recovered': 'A machine told low by `machine.memory_low` has its free memory back over the threshold (issue #868): `freeBytes` of `totalBytes` now, `of` as in `machine.memory_low`.',
  'machine.windows_link_broken': 'A WSL machine\'s client found that Windows does not reach the hopper (issue #712): Windows, through PowerShell, opened `url` (the address check, `/job/address`, at localhost, at the port the client dials the hopper on; the health route at localhost before it) and got no answer. `error` says why; `mode` is WSL\'s networking mode (`nat`, `mirrored`), when read. The Machines view and a banner show the fix. Once per break. `machineId` `windows`: the keep-alive loop on Windows found it and reported it (`hopper windows-link report`), with no client in the distro.',
  'machine.windows_link_restored': 'A machine told by `machine.windows_link_broken` has its Windows link working again (issue #712): Windows reaches the hopper at `url`.', 'machine.offline': 'A machine stayed offline for two minutes (issue #1497): offline at every record of the resource recorder `since` then. A container a host restart left stopped is the usual cause. `label` is its name on the Machines view. Once per stretch offline; after a restart of the hopper, a machine still offline is told again. Webhooks and notifiers take it.', 'machine.back_online': 'A machine told by `machine.offline` is online again (issue #1497): `since` is when it went offline.', 'machine.allocation_failures': 'A machine\'s kernel logged a burst of large page allocation failures (issue #2622 part 6): `count` failures of order 4 or more in the last 10 minutes, the highest of order `maxOrder`; `since` is when the watch saw the burst. Memory there is full and fragmented: in a WSL VM, wsl.exe and interop hang next. Once per burst; after a restart of the hopper, a burst still on is told again.', 'machine.allocation_failures_ended': 'A machine told by `machine.allocation_failures` logged none in the last 10 minutes (issue #2622 part 6): `since` is when the burst was seen.',
  'blast_radius.settings_changed': 'An admin saved the blast-radius settings (issue #542): `from` and `to` where the gate stands (`gateAt`), what passes it (`pass`), the rating rules (`rules`), the actor machines and how often each machine is discovered (`everyMinutes`).',
  'minor_decision.picked': 'Jev was asked for a decider call (issue #550) at a decision point (`point`: `question-risk`, `failure-assessment`, `lane-count`, `job-machine`, `intake-order`, `merge-order`, `intake-trust`, `intake-kind`, `sandbox-request`; `question-answer` only in events from before issue #679) and picked one of its `options` with a `confidence` — or could not (`error`). A `question-risk` pick (issue #679) is the risk call on a level\'s answer: `pick` is the risk (`none`, `low`, `real`) and `categories` its kinds (`credentials`, `destructive`, `publish`, `pay`, `permissions`, `ci`, `data`, `other`). `applied`: the pick was acted on (the point is active, the pick met its `threshold`, and nothing made it consequential); otherwise `notApplied` says why (`shadow`, `below_threshold`, `consequential` with what made it so, `no_pick`, `too_late`: decided before Jev answered, and compared at once) and the decision went on as before. A question\'s pick names it (`questionId`); a `lane-count` pick its machine (`machineId`).',
  'minor_decision.compared': 'What was decided after Jev\'s pick was not applied (issue #550): `actual`, by `decidedBy` (an escalation level, `human`, `person` for a failed job, or `rules` for an ordering the rules made without Jev, issue #796, or for what the keyword risk rules said of a `question-risk` pick, issue #679: `real` when one matched, else `none`; a `low` risk agrees with `none`), and whether it `agreed` with Jev\'s `pick`. Feeds the decision point\'s agreement rate.',
  'minor_decision.overridden': 'A person said what a decider call should have been (issue #550): `actual` in place of Jev\'s `pick`. Counts as a disagreement in the agreement rate unless it names Jev\'s pick.',
  'minor_decision.settings_changed': 'An admin changed a decision point\'s settings (issue #550): its mode (`off`, `shadow`, `active`) and its threshold, `from` and `to`.',
  'job.phase_changed': 'A job moved into another phase (issue #548): `from` and `to` are `work`, `research` or `proposal`. A switch from a question (`mode: "switch"`, the `questionId`, the person or level `by`, the scoping `note`) moves it into research or a proposal in the same session; accepted, the person picks whether it goes back to `work`, ends, or goes on from research to a proposal. `reason`: the note, or what moved it.',
  'job.forked': 'A separate research or proposal job (`forkId`) was spun off a job\'s question (issue #548), by a person or an escalation level the phase-shift settings allow (`by`), about the aspect in `note`. The parent keeps waiting on its question (`parent: "waiting"`) or was parked (`"parked"`). The fork carries the parent\'s priority; its accepted result answers the question.',
  'job.fork_resolved': 'A fork\'s research report or proposal was decided (issue #548). Accepted, it is the answer to the parent\'s question when that is still open (`delivered`); rejected, the question stays open. `question`: the question\'s status at the decision (issue #570): `answered` when a person or a level answered it while the fork ran, and an acceptance delivered nothing.',
  'tldr.written': 'A cheap model (Claude Haiku) wrote the TL;DR of a long card (issue #569): `kind` (`question`, `research`, `handoff`; a proposal has its own TL;DR part, issue #651) and its `id`, the `text` — one or two plain sentences, no Markdown or HTML — and the `model` that wrote it. Written once per text: again only when the card\'s text changes (a research report\'s next round). The card leads with it; a notification sent before it shows the agent\'s own summary.',
  'tldr.settings_changed': 'An admin turned the TL;DR on or off (issue #569): `enabled`, `from` and `to`. Off, no TL;DR is written or shown, and notifications carry none.',
  'remote_access.changed': 'The hopper\'s admin changed remote access (issues #880, #968), `from` and `to`: on or off (`enabled`); the provider picked (`provider`: `cloudflare` or `ngrok`); the host name asked for (`domain`); when the admin last started the tunnel again (`restartedAt`); what the hopper minted at the provider (`provisioned`: the host name, and the ids it removes again — at Cloudflare the account, zone, tunnel and DNS record, at ngrok the tunnel credential and a domain it reserved; none of them a secret); `leftover`: what a release could not remove at the provider. `credential`: the provider\'s credential was `set` or `removed` (never its value: it is the system secret `remote-access.cloudflare-api-token` or `remote-access.ngrok-api-key`). `by` is `hopper` when a start moved NGROK_AUTHTOKEN from the environment. An instance event: in every user\'s log.',
  'cloud_link.linked': 'The hopper\'s admin linked this install to an account at hopper.io (issue #467): the link record is written in the instance\'s settings, and nothing else changes. `installId`, the instance id (issue #465); `account`, the hopper.io account; `by`, who. An instance event: in every user\'s log.', 'cloud_link.unlinked': 'The hopper\'s admin unlinked this install from hopper.io (issue #467): the link record and its open registration code (issue #465) are removed, and nothing else changes. `installId` and `account`, the link that ended; `by`, who. An instance event: in every user\'s log.', 'cloud_link.registration_code_minted': 'The hopper\'s admin minted a registration code for the cloud link (issue #465): a one-time code the hopper.io account owner enters at hopper.io to register this instance, answered once and kept only hashed, in place of any code before it. `installId` and `account`, the link; `expiresAt`, when the code ends (10 minutes); `by`, who. Never the code. An instance event: in every user\'s log.', 'cloud_link.registered': 'The cloud link registered at hopper.io (issue #465): hopper.io handed back the open registration code for the link\'s own account, and the instance spent it. The link\'s state is now `registered`. `installId` and `account`, the link. An instance event: in every user\'s log.', 'allowed_hosts.changed': 'The hopper\'s admin changed the allowed hosts (issue #1024): the host names and addresses the UI answers to beyond the LAN names and the ones this host has on its tailnet. `from` and `to` are the whole lists; `by`, who. An instance event: in every user\'s log.', 'telemetry.changed': 'The hopper\'s admin changed the telemetry setting (issue #1486, design.md "Telemetry settings"): whether the hopper exports its traces, metrics and logs over OTLP, the endpoint, and which signals. It applies at once, while the launch\'s OTEL_* variables name no exporter. `from` and `to` are the whole settings: `on`, `endpoint` (an http or https URL with no user, password or query), `signals`; `by`, who. Never a header or a credential. An instance event: in every user\'s log.', 'source_email_match.changed': 'The hopper\'s admin turned the source email match on or off (issue #1380): whether a GitHub account a person connects from Sources must have, among its verified emails, the email they signed in with. `on`, the new setting; `by`, who. An instance event: in every user\'s log.', 'cloud_link.unregistered': 'hopper.io removed this instance (issue #465): its account owner unregistered it there, and hopper.io said so over the cloud link. The link\'s state is `pending` again and its `registeredAt` is gone; the link record stays, and nothing else on the instance changes. A new registration code registers it again, with the same id. `installId` and `account`, the link. An instance event: in every user\'s log.', 'cloud_link.message_refused': 'The instance refused a message hopper.io sent over the cloud link (issue #465): it was larger than 1024 bytes (`too-large`), not JSON (`not-json`), of a type other than `register` or `unregister` (`unknown-type`), or not of that type\'s closed shape (`bad-shape`); or one too many in a minute (`too-many`), which also closes the connection. Nothing changed on the instance. `reason`, why; never the message. An instance event: in every user\'s log.', 'cloud_link.connected': 'The cloud link connected to hopper.io (issue #2039, design.md "The cloud link\'s connection"): the instance checked hopper.io by TLS and the pin of its key, its hello proved the cloud link key, and hopper.io took it. From here the instance sends its heartbeat and, while registered, its state snapshot. `installId` and `account`, the link. An instance event: in every user\'s log.', 'cloud_link.disconnected': 'The cloud link\'s connection to hopper.io ended (issue #2039): it was lost, hopper.io closed it, or an unlink, a key change or a stop closed it. The agent tries again with backoff (1 second, doubling, at most 5 minutes) while the link record exists. `installId` and `account`, the link; `code`, the WebSocket close code (`1000` closed by the instance, `1006` lost, `4000` another connection of this instance took its place). An instance event: in every user\'s log.', 'cloud_link.connection_refused': 'A connection to hopper.io was refused (issue #2039): by the instance before its hello — hopper.io\'s key does not match the pin in the code (`pin`), its certificate is not good (`tls`), or it answered with no WebSocket (`http`) — or by hopper.io after the hello: too many connections (`too-many`), a hello it does not take (`bad-hello`), another key than the one its registration holds (`unknown-key`), or no hello in time (`hello-timeout`). Recorded once while the same refusal repeats. `installId` and `account`, the link; `reason`, why. An instance event: in every user\'s log.', 'cloud_link.revoked': 'The cloud link key was revoked (issue #2039, docs/hopper-io-security.md R4): by hopper.io (`by` is `hopper.io`), when its account owner removed this instance there or deleted the account — the agent does not connect again until the admin rotates the key —, or by the hopper\'s admin on this instance (`by`, who), which drops the key and keeps the link with no key until a rotation. `installId` and `account`, the link. An instance event: in every user\'s log.', 'cloud_link.message_dropped': 'The instance did not send a message to hopper.io (issue #2039, docs/hopper-io-security.md R4, R7): the outgoing scan found a secret in it (`secret`), or it was over its cap (`too-large`: 1024 bytes, or the snapshot\'s 192 KiB). Nothing of it left the instance. `message`, which kind; `reason`, why; never the message. An instance event: in every user\'s log.', 'display_name.changed': 'The hopper\'s admin changed the instance\'s display name (issue #465): what they call this hopper, shown in Settings → Version beside its instance id. `from` and `to` are the names, empty when none; `by`, who. An instance event: in every user\'s log.',
  'github_rate_limiter.settings_changed': 'The hopper\'s admin changed the shared rate limiter\'s settings (issue #436): below which share of a GitHub rate limit, in percent, calls are spread to its reset (`slowBelowPercent`), how many calls are kept in reserve (`reserve`), how many polls run at once in a batch (`batchSize`), and how many calls intake leaves for job work (`intakeReserve`, issue #983), how often intake lists the job repositories, in minutes (`intakeSyncMinutes`, issue #985), and how often the in-motion cycle reads the pull requests in motion, in minutes (`prCycleMinutes`, issue #985); each absent from a change made before it. `from` and `to`. An instance event: in every user\'s log.',
  'token_budget.settings_changed': 'An admin changed the token budget (issue #2302): the most one job may spend before it is paused, in tokens (`jobTokens`: input, output, cache read and cache write) and in estimated cost (`jobCostUsd`, US dollars); and (part 5) the most the jobs may spend in one UTC day before a waiting job is held, in all (`dayTokens`, `dayCostUsd`) and per repository (`repoDayTokens`, `repoDayCostUsd`; absent in an event from before them: off); 0 turns a cap off. `from` and `to`.', 'auto_park.settings_changed': 'An admin changed the auto-park settings (issue #650): how many minutes a question waits on a person before its job parks by itself (`minutes`), and the same for a high-priority job (`highPriorityMinutes`); 0 turns it off. `from` and `to`. No longer written (issue #2335): a job that waits on a person parks with no setting.',
  'question.thread_held': 'A question at the human stage of a GitHub job waits on a person before it goes on its issue thread (issue #435): the policy for the repository (`otherRepos` or `ownRepos`) is `review`. Approve it to post it; an answer in the hopper works as before.',
  'question.thread_approved': 'A person approved a held question for its issue thread (issue #435); the next sync of its source posts it (`question.thread_posted`).',
  'question.thread_posted': 'A question at the human stage of a GitHub job went on its issue thread as one comment (issue #435), `url`. Its job is parked; the first reply by the connected account or a maintainer of the repository (author association owner, member or collaborator) answers it (`question.answered`, `by: thread:<login>`) and resumes the job. `approvedBy`: who approved it; absent: the policy posted it with no review.',
  'thread_ask.settings_changed': 'An admin changed the policy for asking on the issue thread (issue #435): for repositories the connected account owns (`ownRepos`) and for any other (`otherRepos`), `post`, `review` or `off`. `from` and `to`.',
  'auto_answer.settings_changed': 'An admin changed the auto-answer settings (issue #632): whether a level\'s answer goes into the job with no person (`enabled`), the least confidence it needs (`threshold`: `low`, `medium` or `high`), and whether a high-priority job\'s question goes to a person (`holdHighPriority`, issue #679; absent before it), `from` and `to`.',
  'phase_shifts.settings_changed': 'An admin saved the phase-shift settings (issue #548): the default mode (`fork` or `switch`), what a parent does while its fork runs (`wait` or `park`), and the escalation levels that may shift a job themselves.',
  'job.gate_passed': 'A person let a job held at the blast-radius gate through (issue #542): it may run on a gated machine. `reason`: the hold it had.',
  'queue.gate_changed': 'The queue gate was changed: its mode (`auto-accept` or `review`) or its throttle (`autoAcceptPerHour`, null for none).',
  'job.pull_request_merged': 'A finished job\'s pull request, followed after its end (issue #579), was merged: its item is done (`hopper:done` on GitHub). `part`: it shipped part of the item, and the next part may now be taken; a merge that did not close the item is a part (issue #721), and a merge recorded as the whole item before issue #721 that did not close it is recorded again, once, as a part. A part that makes every part the item declares done marks the item done (issue #729). `byHopper`: the hopper merged it itself (yolo mode on for its repository, issue #637). `person`, `via`: a person pressed Merge now (issue #677), in the UI or the operator CLI. `stray` (issue #1420): no job followed it — a job named it, and no job of its item worked on it — and it was merged on GitHub; it moves no work item, only marks its own pull request merged.',
  'job.pull_request_closed': 'A finished job\'s pull request, followed after its end (issue #579), was closed without a merge: its item is flagged (`hopper:pr-closed` on GitHub) until a person acts. `part`: it shipped part of the item. `person`, `via`: a person pressed Close PR (issue #677), in the UI or the operator CLI. `superseded` (issue #1143): the hopper closed it itself, as nothing was left to land, and why: its issue was closed as completed by another pull request (the item is done, `hopper:done`), or its base branch already has every commit of it. `stray` (issue #1143 part 4): no job followed it — a job named it, and no job of its item worked on it —; the close ends no wait of its item. A stray closed on GitHub, with no `superseded`, is recorded too (issue #1420).',
  'job.pull_request_abandoned': 'A finished job\'s item was closed as not planned on GitHub while its pull request, followed after its end, was still open (issue #428): the job is abandoned upstream. The hopper follows the pull request no more and never merges it, and leaves it open; `hopper:pr-ready` comes off and no end label goes on. A reopened issue with that pull request still open is followed again. `part`: it shipped part of the item.',
  'job.finish_briefed': 'A job that ended done left its own pull request with merge conflicts, failing checks or as a draft (issues #626, #736): one fixed step finishes it, so the job goes on in its own session with that step\'s fixed brief, in place of a failure and a hand-off. `step`: `rebase` (onto its base branch; merge conflicts come first), `fix_checks` (its failing checks, issue #736) or `mark_ready` (a draft, marked ready for review). At most three per run; then the job is judged as any other.', 'job.checks_rerun': 'A job ended done while the checks of its own pull request were red (issue #1230, the cause Own PR checks red): before it is sent back to fix them, the hopper ran its failed checks again once, the flake guard, once for each head commit. `recordId`: its failure record. `pullRequest`, `head`: the pull request and its head commit. `checks`: the checks run again, by name; none when none could be. `refused`: why a check was not run again (no GitHub Actions job, no Actions write permission). Red again, the job goes on to fix them (`job.continued`).', 'job.checks_rerun_asked': 'The hopper asks GitHub to run the failed checks of a job\'s own pull request again (issue #1607): recorded before it asks, so a stop while it asks makes no second run again of the same head commit. Fields as `job.checks_rerun`; `checks`, the checks it asks to run again. With no `job.checks_rerun` after it, the hopper stopped meanwhile: whether any check ran again is not known, so the job may run them again itself.',
  'job.pull_request_base_merged': 'A PR waiting job\'s pull request had merge conflicts with its base branch, and the hopper merged the base branch into it in its own mirror and pushed the merge commit to its branch (issue #967): no job, no lane. `commit`: the merge commit. `resolved`: the Markdown files whose conflict it resolved by keeping the lines both sides added, the base branch\'s first. The job still follows the pull request; its checks run again. A conflict it does not resolve goes to a tend job (`job.pull_request_tended`).', 'job.companion_merged': 'A **companion pull request** of the job (a pull request a job of its item opened through the hopper, in any GitHub repository, that the job does not follow) was open, ready and in a repository whose merge gate lets the hopper merge it (yolo mode on for that repository, or its change kind merged with no person), and the job\'s done criteria were met: the hopper merged it through the merge gate, as a followed pull request (issue #2752 part 3). `pullRequest`: the companion. It ends the companion only: the item and the job\'s followed pull request are as they were.', 'job.companion_rebase_filed': 'A **companion pull request** of the job had merge conflicts with its base branch while its work item was done or its issue closed, and the hopper\'s own merge of the base branch could not resolve them (issue #1143 reopened). A tend would run the item again and reopen its issue, so the hopper filed one **companion rebase issue** on the item\'s repository instead: with the job sources\' label and assigned to the connected account, so Intake takes it as any other work, and its job updates the companion\'s branch. `pullRequest`: the companion; `issue`, `url`: the issue filed. Once for each head commit of the companion, at most three times. The item and its issue are as they were.', 'job.pull_request_retargeted': 'A followed job\'s open pull request had a base branch that is not its repository\'s landing branch (its landing batch setting, never GitHub\'s default branch) and is no open pull request\'s head: the hopper changed its base to the landing branch (issue #1143), with no job, and said so in one comment on it. `from`: the base before; `to`: the landing branch. `stray` (issue #1143 part 4): no job followed it — a job named it, and no job of its item worked on it.',
  'job.pull_request_tended': 'A PR waiting job\'s pull request got merge conflicts with its base branch, or failing checks, while it waited (issue #736): the hopper ran its item again (`job.rerun`, by `tending`) with the tend brief, so a new job brings the same pull request back to ready, and this job follows it no more. `step`: `rebase` or `fix_checks`. `nextJobId`: the new job. A rebase is never capped (issue #786); at most three `fix_checks` tends in a row of one pull request, then it waits on a person. `person`, `via`: a person pressed Tend again (issue #1010) after the hopper gave up on it, in the UI or over the API.',
  'job.pull_request_followed': 'A done job — or a failed one that is no failed tend, issue #786 — that followed no pull request — it ended before the hopper followed pull requests, or its follow ended — is the newest job of its item, and its item is open, or closed as completed with an open pull request that closes it by keyword or ships part of it (issue #786), and has an open pull request on its source (issue #763): the sync loop reconciled it, and the job follows that pull request from now on, as PR waiting. It shows on the Pull requests list, and yolo mode merges it and tending tends it as any followed one. `part`: it ships part of the item ("Part of #N").', ...WORK_ITEM_EVENT_DOCS, ...TAGGED_EVENT_DOCS, ...PUSH_REQUIREMENT_EVENT_DOCS, ...DELIVERY_SETTINGS_EVENT_DOCS,
  'contribution.changed': 'An admin turned Contribution on or off (issue #429): whether a job of a repository its user cannot push to may work through a fork — the hopper forks it into the user\'s account, the job pushes there and opens its pull request on the repository from the fork. `from` and `to` (`on`), and `by`, who. It applies to the next request a job makes.', 'credential_check.changed': 'An admin turned strict mode of the credential check on or off (issue #1467): on, a machine whose job user holds infra credentials takes no job until an admin uses it anyway; off, it takes jobs with a warning. `from` and `to` (`strict`), and `by`, who. It applies at the next decision.',
  'shrink_guard.changed': 'An admin changed the shrink guard\'s percent (issue #1096): a job\'s push that brings in its base branch is refused when it takes more than this percent of a file\'s lines, or empties or removes it, and the branch\'s own change did not. `from` and `to` (`percent`), and `by`, who. It applies to the next push.',
  'yolo_mode.changed': 'An admin changed yolo mode (issue #579): whether jobs may merge their own pull requests once the repo\'s checks pass — `on` for every job repository, `repos` per repository (`owner/repo`, lowercased), which wins. `changeKinds` (issue #1076): the change-kind rules over the built-in rule, `default` and per repository, and the merge gate of each kind. `push` (issue #1806): direct push\'s repositories, where a job may push straight to the target branch as a fast-forward; absent: none. `from` and `to` the settings, `by` who changed them. Done never depends on it.',
  'vault.secret_set': 'A vault secret was set (issue #558): `replaced` when it already held a value. Its name and who set it; never its value. `backend`: the vault backend it is kept in (issue #585), when it is kept in one: the hopper holds no value for it. `rotated`: a system secret (issue #658) the hopper made or renewed itself — a webhook secret rotated, a GitHub token renewed. `mints`: the AWS account or cluster it is a minting credential for (issue #580).',
  'vault.secret_removed': 'A vault secret was removed (issue #558), and who removed it.',
  'vault.secret_read': 'The hopper read one of its own secrets in the vault\'s system scope (issue #658), for `purpose`: at most once an hour per secret, since some are read at every source poll. `by` is always `hopper`: no job reads a system secret. Never the value.',
  'vault.master_key_rotated': 'The hopper\'s admin rotated the master key (issue #659): every secret the old key sealed, in every vault, was sealed again under a new key in one transaction (`resealed`); `unreadable` counts the ones the old key sealed that did not open, left as they were. `from` and `to` are the two keys\' short fingerprints, never a key; `by` pressed it. The new key is shown once, to them. Appended to every user\'s log.',
  'vault.secret_migrated': 'One of the hopper\'s own secrets moved into the vault\'s system scope at start (issue #658), from where it was kept before (`from`: `connected_accounts`, `webhooks`, `sign-in`); it was opened again before the old copy was removed. Never the value.',
  'template.saved': 'A template was saved (issue #558): its image, the tools the hopper adds to it (issue #716), its `egress` hosts when it names any (issue #1875: each `host:port` its boxes may reach through the egress proxy), its `bastionTargets` when it names any (issue #2146: each target a bastion of it may forward to), and its scope, the vault secrets its boxes may ask for, its operation profiles (issue #584) — a `terraform-workspace` profile with its state `backend` (`bucket`, `region`, `keyPrefix`; issue #715), which the read-only check probes and no approval covers —, its `probeMarks` when it has any (issue #916: a read probe of the read-only check marked `expect-denied` or `skip`), and who saved it. A scope wider than the one approved, a new image, a new egress host, or a new bastion target, waits for a person (`vault.approved`); a new profile waits for its approval (`template.profile_approved`).',
  'template.checked': 'The read-only check of a template ended (issue #716): `passed`, or `failed` with the probes that failed and any problem. A probe the check did not run (`not-run`, issue #715: a workspace need with no state backend) is a failed probe: unproven, never passed. A template a job asked for with read needs only, or read and observe needs (issue #2146), takes no box and no job until the check of its current version passed. `artifact` (issue #715): the artifact that holds its report, of the job that asked for the template; absent when no job did.',
  'template.check_requested': 'A person asked for the read-only check of a template to run again (issue #716), or (issue #1779) a minting credential was set for the account or cluster of a read need its failed check got no credential for (`by` `minting credential <name>`): its last check is dropped, and the next check pass runs one.',
  'template.removed': 'A template was removed (issue #558): only when no box of it was attached (issue #604); its access approvals are revoked.',
  'vault.approved': 'A person approved a template as it is (issue #558): its image (with its tools, issue #716), its egress hosts (issue #1875), its bastion targets (issue #2146) and its whole scope. From then on its boxes take jobs (issue #602) and may be given those vault secrets, and only those. Its read profiles are approved with it (`template.profile_approved`); a write, sync or apply profile is not. `by`: a person, or for a template made for a job `the read policy`, `the auto-approve policy` (issue #1001), `a remembered write approval` (issue #1001) or `skip template approval`. `jobs` (issue #2197 part 3): a run card approved with no allow again approves those jobs\' runs only; absent, every job\'s.',
  'vault.read_policy_set': 'An admin set the read policy (issue #716): the assets the hopper approves read on with no person, for a template a job asks for (`sandbox-template`, `sandbox`). The read policy never approves write, sync or apply: only skip template approval does (issue #991). Empty: the read policy approves nothing.',
  'sandbox.strictness_changed': 'An admin changed the sandbox strictness in Vault (issue #655, brake 2): which sandbox runs gate 2 may approve with no person, `default`, by blast radius level (`radius`) and by template (`templates`). `relaxed` and `standard`: the approval toggles and policies decide; `strict`: a person approves each run of a medium or high radius template, or one with no rating; `locked`: a person approves each run. It applies at once. `from` and `to`, `by` who changed it.', 'vault.sandbox_approvals_set': 'An admin set the sandbox approval toggles (issue #991): `skipTemplateApproval`, a template the hopper makes for a job is approved at once, its write, sync and apply profiles with it; `skipSandboxApproval`, a box a job asks for starts at once, a high-blast-radius one too. Both on is sandbox YOLO. `autoApprove` (issue #1001): the blast radius levels whose templates and runs are approved with no person. `rememberWritesHours` (issue #1001): how long a person\'s write, sync or apply approval is remembered; 0, until an admin forgets it. Issue #1472: `standingReadGrant`, the standing read grant: a job on a box of a template that only reads what the read policy holds gets the vault grant with no person.',
  'vault.sandbox_requested': 'A running job asked the hopper for a box of a template (issue #991, `sh "$HOPPER_SKILL" sandbox --needs …`, or `--template NAME`, issue #1471), or the hopper asked for one before the job started, as the job\'s prompt names the template (issue #1471): the sandbox request `request`, kept in memory. It waits for a person on Access requests unless skip sandbox approval is on. On the job\'s timeline.', 'vault.run_card_opened': 'A new **run card** (issue #2197, design.md "One approval per sandbox run"): the job\'s run of `template`, or its ask that waits on it, waits for a person on Access requests. `waits` says what the one approval approves: the template (its image, tools, egress, secrets or profiles), the run, or both. `purpose`: why the job asks, in its words. One per job and template while the hopper runs; not while Jev reads the run. The notifiers send it (the Grok Bot routine as `vault.run_card_opened`, with the job\'s priority and the Access requests link). On the job\'s timeline.',
  'vault.sandbox_approved': 'A sandbox request was approved (issue #991): `by` a person, `skip sandbox approval` when the toggle approved it, `the auto-approve policy` with the template\'s `radius` (issue #1001), `the template\'s approval by <person>` when a person approved the template this job asked for, or `a remembered write approval` (issue #1001) when a person approved each change the template makes before, or `the approval of job <id>, which it runs again` when a person approved the same run for the job this one runs again (issue #2639 part 2), or `Jev` when Jev\'s sandbox check (issue #655 part 13, the decision point `sandbox-request` active) allowed a run one of those would approve. It starts no box (issue #1349): the job\'s box steps then run, each in a sandbox of its own, burned after it. On the job\'s timeline.',
  'vault.sandbox_declined': 'A person declined a sandbox request (issue #991), with the `reason` the job is told. No box starts. On the job\'s timeline. Issue #655 part 9: `by` is `the hold timeout` when no person answered it within 24 hours; that deny is of this request only, and lowers no trust. Part 13: `by` is `Jev` when Jev\'s sandbox check (the decision point `sandbox-request` active) denied it, with its reason: a deny at gate 2, which lowers the job\'s trust as a person\'s does (`job.trust_lowered`, `job.quarantined`). Part 16: `by` is `the minimum trust` when the template has an operation profile whose minimum trust the job\'s stamp does not meet: declined at once, by policy, before Jev or a person; the job\'s trust stays.',
  'vault.sandbox_started': 'The box of a sandbox request started (issue #991): `container`, the sandbox box, which joined as a machine. Recorded until issue #1349; an approval now starts no box. On the job\'s timeline.',
  'vault.write_forgotten': 'An admin forgot a remembered write approval (issue #1001): the `operation` on the `asset` a person approved before. A later template or sandbox run that changes it waits for a person again.',
  'vault.sandbox_failed': 'The box of an approved sandbox request did not start (issue #991): `reason`. Recorded until issue #1349; an approval now starts no box. On the job\'s timeline.',
  'vault.revoked': 'A person revoked a template\'s approval (issue #602). Its boxes take no new job, and are given no vault secret, until a person approves it again (`vault.approved`). Every access approval of its operation profiles is revoked with it.',
  'template.profile_approved': 'An operation profile of a template was approved in access (issue #584): with the template for a read profile (level low), or by its own explicit approval for a write, sync or apply profile (level high). Access then allows the template\'s jobs that operation on that asset.',
  'vault.agent_credential_given': 'A box the hopper launched was given its template\'s agent credential at its launch (issue #708, part 10): a Claude token, in the box\'s environment as `CLAUDE_CODE_OAUTH_TOKEN`, so its agent starts signed in. The secret\'s name, the template and the box; never the value. `backend`: the vault backend it was read from, when it is kept in one.', 'vault.pod_credential_given': 'A job pod, or a lane pod, was given its user\'s Claude token at a start of its job (issue #1287): the vault secret the kubernetes executor names (`agentCredential`; on a lane pod `CLAUDE_TOKEN`), a token `claude setup-token` printed, in the job\'s pane as `CLAUDE_CODE_OAUTH_TOKEN`, so Claude in the pod starts signed in. The secret\'s name, the pod and the job; never the value. `backend`: the vault backend it was read from, when it is kept in one.',
  'vault.delivered': 'A vault secret was delivered to a box, for a job at work on it (issue #558): sealed to the box client\'s own request, never in an environment or a file. The secret\'s name, the template, the machine and the job; never the value. `backend`: the vault backend it was read from at that moment (issue #585), when it is kept in one.',
  'vault.minted': 'The vault minted a short-lived credential for a job on a box (issue #580): an AWS role session (`aws`) or a Kubernetes token (`kube`) for the operation on the asset, from the minting credential named, after Access allowed it. `decision` is the id of Access\'s decision (Users & access → Access); `renewal` when the job had one for that profile before. `plan` (issue #870): the approved, current plan an operation that changes infrastructure named. `principal` (issue #871): who the credential writes as, as an audit log names it (the assumed role\'s session, the service account), so a write it made while valid is not out of band. `bound` (issue #1371): the Secret a need box\'s Kubernetes token is bound to; deleting it (`vault.unbound`) ends the token. `actions` (issue #2206): the granted AWS actions, each on its resource, a need step\'s session was narrowed to. A mint that names a plan and is no renewal is an apply: the notifiers send it as `infra.plan_applied`, with the watchers of the plan\'s environments (issue #870 part 4). Never the credential.',
  'vault.mint_tested': 'A person tested a minting credential (issue #781, `hopper vault mint-test`): the vault minted a read session for the `aws-role`, as for a job, and asked STS who it is; or (issue #854) a read token for the `cluster`, and asked the cluster who it is and which namespaces it lists. `arn` is the role the session assumed, with `sessionName`; `user` is who the cluster says the token is, with `sessionName` when it signed in through EKS; `roleArn` and `account` the role a session or an EKS token signed in as (issue #1766), and `credential` the minting credential the test used — for a cluster found in the AWS accounts, the AWS one it was found with; `reason` when nothing was minted or STS or the cluster refused. Never a key or a token.', 'vault.discovery_minted': 'Topology discovery (issue #1781 part 3, design.md "The infrastructure topology") asked the vault for a read credential: a read session of an account\'s read role (`aws-role/<account>/hopper-read`), or a read token for a `cluster`. `credential`: the minting credential it came from (for a cluster found in the AWS accounts, the AWS one); `expiresAt` when it was minted; `reason` when nothing was minted. Never a key or a token. On no job\'s timeline.',
  'vault.check_minted': 'The vault minted a short-lived read credential for a read-only check box of a template (issue #797): an AWS role session (`aws`) or a Kubernetes token (`kube`) for the read need on the asset, from the minting credential named, after Access allowed the template it (`decision`, a decision of the check on Users & access → Access). The check runs no job; `check` is its check box. `bound` (issue #1371): the Secret a Kubernetes token is bound to, deleted when the check box ends (`vault.unbound`). Never the credential.',
  'vault.binding_named': 'The vault named the Secret a sandbox\'s Kubernetes token is to be bound to (issue #1628), before it asked the minting credential for the token: the minter makes that Secret. `box` is the need box or check box, `job` the job it served (none for a check box), `credential` the minting credential. A hopper that stopped before the mint\'s own event (`vault.minted`, `vault.check_minted`) still knows the Secret: the reconcile pass deletes it (`vault.unbound`) once no sandbox holds it. Never the token.', 'bastion.started': 'A job started a bastion (issue #2146, design.md "Bastions"): one need box of `template` that holds `kubectl port-forward` to each of `targets` (`<cluster>/<namespace>/<kind>/<name>:<port>`) on 127.0.0.1 inside it, its kube tokens minted for its observe profiles (each a `vault.minted` with `box` as its machine) and minted again while it runs, and, part 6, the vault `secrets` it holds for bastion reads, by name (each a `vault.step_delivered` with `box` as its host). It ends at `expiresAt` unless it is used before. Never a token or a value.', 'bastion.ended': 'A bastion ended (issue #2146): `reason` `stopped` (by the job, a person or the hopper, `by`), `expired` (its TTL passed with no use), `job-ended`, or `failed` (a renewal was refused, or its box ended by itself: `problem`). Its tokens are released and its box burned.', 'bastion.relayed': 'A job\'s relay connection to `target` of its bastion ended (issue #2146 part 3, design.md "Bastions"): Access allowed it (`bastion#can_relay`, the target approved with the bastion\'s template), it opened at `openedAt` and was open `ms` milliseconds. Never what went through it.', 'bastion.relay_refused': 'A job\'s relay connection to `target` of its bastion was refused (issue #2146 part 3): Access denied it, or could not be asked (`reason`); no command started in the box.', 'bastion.read': 'A bastion read ran (issue #2146 part 6, design.md "Bastions"): one HTTP `method` (GET, or a POST to Grafana\'s data source query) of `path` on `target`, run with curl in the bastion\'s box over a relay connection Access allowed, with a vault secret\'s header from its file there when the job named one. `status` and `bytes`: the target\'s answer; `problem`: why there was none (curl\'s words, or an answer over 2 MiB). `ms`: how long it took. Never the secret or the answer.', 'database.role_minted': 'A database read\'s role was minted (issue #2231, design.md "Database reads"): after Access allowed `template` read on the database `asset` (`decision`), the vault made the login role `role` in it with the minting credential `credential`: SELECT only on the schemas the credential names, read-only by default, two connections, valid until `expiresAt` at most. `read` is the read\'s id. Its password is made in the hopper and never leaves it: never in an event.', 'database.role_dropped': 'A database read\'s role was dropped (issue #2231): `reason` `read-ended` (its read ended, whatever happened) or `expired` (the sweep found its `VALID UNTIL` passed: a hopper that stopped mid-read left it). Its sessions were ended first.', 'database.read': 'A database read ran (issue #2231, design.md "Database reads"): `sql`, the job\'s one SELECT, as `role` in a read-only transaction on the database `asset`, after Access allowed it (`decision`). `rows` and `bytes`: the CSV it answered; `problem`: why there was none (what the database said, or an answer past the cap). `ms`: how long it took. Never a row of the answer or a password.', 'database.read_refused': 'A job\'s database read was refused before any role was minted (issue #2231): Access denied it (`decision`), no minting credential mints for the database, or the mint failed (`reason`).', 'vault.unbound': 'A sandbox ended, and the Secret its Kubernetes token was bound to was deleted (issue #1371): the API server refuses that token at once. `box` is the need box or check box, `job` the job it served (none for a check box), `credential` the minting credential that made the token. Its end does it, whatever the outcome; the reconcile pass, at start and every 5 minutes, does it for a binding a hopper that stopped, or an unbind that failed, left. Never the token.', 'vault.check_mint_refused': 'A read-only check box of a template got no read credential for one read need (issue #797), and the check failed with the reason: the vault mints for none of the asset\'s kind (`mint.kind` absent), Access denied it, no minting credential covers the asset, or the outside service refused. `decision` when Access answered; never a value.',
  'vault.mint_refused': 'A box asked the vault to mint a credential and got none (issue #580): Access denied it — the profile waits at the first-time gate on Vault, or the template does not declare it —, or no minting credential covers the asset, or the outside service refused. `decision` when Access answered; never a value.',
  'vault.refused': 'A box asked for a vault secret and was refused (issue #558): a template not approved for it, a machine of no template, a job not at work there, a token the hopper did not give, a vault backend that is gone or cannot read it (`backend`, issue #585). Or a launch\'s agent credential was refused (issue #708, part 10): its template is not approved for it, or its value is no Claude token; then `machine` is the box that was not started, and there is no `job`. `reason` says which; never a value.',
  'vault.credential_asked': 'A job on a box loaded a skill whose credential its template does not give (issue #583), and the hopper asked a person for one: a credential request. The skill, the template, the machine, the job, and what the job said it needs it for. Once per job and request.',
  'vault.credential_given': 'A person gave a credential for a credential request (issue #583): a vault secret, added to the template\'s scope. The secret\'s name, the kind they gave, whether the giving approved it for the template (an approved template whose image is unchanged), and the jobs that waited; never the value.',
  'vault.credential_declined': 'A person declined a credential request (issue #583): each job that waited on it is told the reason when it asks again, and goes on without it or fails.',
  'vault.grant_asked': 'A job on a box asked the vault for a secret or a minted credential, or a job\'s Windows sandbox step asked for a vault secret (issue #731), or its box step (issue #1875), and its item has no vault grant (issue #652): it was refused, and the hopper asked a person to grant it the vault (Vault). The job, its item\'s key, the machine and the template (a box), the `windowsHost` (a Windows step), or the need `box` and the template (a box step), and the first thing it asked for (a secret\'s name, or `<kind> <operation> <asset>`). Once per job.',
  'vault.granted': 'A person granted a job\'s item the vault (issue #652), after Access allowed it (OpenFGA `vault_grant#can_grant`) — on Vault, or as the submitter of a direct job that authorizes `vault` (issue #901): its jobs — this one, and those Run again or Rework make — get what their box\'s template gives. `by` who granted it; a delegate approver\'s (issue #1138) names the delegate and the person it acts for; `standing read grant` (issue #1472) when the user\'s standing read grant gave it, with no person, to a job on a box of a template that only reads what the read policy holds.',
  'vault.grant_revoked': 'A person took back a job\'s item\'s vault grant (issue #652): its jobs get nothing from the vault again until a person grants it again. `by` who took it back. A quarantine of the job takes it back too (issue #655 part 6): `by` `quarantine by <person>`.', 'vault.grant_denied': 'A person, or a delegate approver for them (issue #1138), denied a job\'s vault grant ask: the ask goes, and the job, which still has no vault grant, asks no more. `by` who denied it; a delegate\'s `by` names the delegate and the person it acts for.', 'vault.action_asked': 'A job\'s need step named an AWS action its change needs (issue #2206, `--action`), and no action grant covers it: the `role` (`<account>/<role>`), the `action` and its `resource`, and the job\'s `why`. The step waits; a person grants or declines it on Access requests. Once per job and scope.', 'vault.action_granted': 'A person granted an AWS action on a resource for an aws-role (issue #2206): a need step\'s change on that role is minted narrowed to the reads and the granted actions, and a later ask of the same scope is covered until the time limit of remembered write approvals. `job`: the job whose ask it answered. `by` who granted it.', 'vault.action_declined': 'A person declined a job\'s ask for an AWS action (issue #2206): its step is told no. `reason` when they gave one; `by` who declined it.', 'vault.action_revoked': 'A person revoked an action grant (issue #2206): the next ask of that role, action and resource waits for a person again; a credential minted before keeps its 15 minutes. `by` who revoked it.',
  'skill.listed': 'A running job asked the hopper what it can set up (issue #582) and was answered the catalog. `machine` and `template`: the job\'s machine and the template it joined as, when it has one.',
  'skill.loaded': 'A running job loaded a skill (issue #582): `skill`, and for a link the `asset` and Access\'s `decision` (issue #559) that allowed it. The answer names the vault secrets the box may use, never a value. `version`: for a built-in library skill loaded by name (issue #1909), the version the job got, and `asset` the file of it, when it is not the entry. `repoCopy`: the repository\'s own copy of that skill the job said it follows (`--repo-copy`): its folder in the repository, the git `tree` and `commit` that hold it, and whether it had `changed` files.',
  'skill.refused': 'A running job asked for a skill and was told no (issue #582), with `reason`: a skill the hopper does not have, no asset or a wrong one, a machine of no template, Access denied it (`decision`), or no vault secret to give.',
  'artifact.created': 'A running job put a file on the hopper for a person to see (issue #624): its title, file name, media type, size and SHA-256, and the issue of the job. `masked`: how many GitHub tokens were masked in it before it was kept (issue #597). `summary`: one line that says what it shows (issue #675). `warning`: it was kept, but an HTML page shows nothing — no `<svg>`, `<canvas>`, `<img>` or `<script>` —, or it has no summary (issue #675). Also on the job\'s stream.',
  'artifact.shared': 'An artifact was shared (issue #624): with another user of the hopper (`user`, their name), or as a public link that works until `expiresAt`. `by`: the person, or `job <id>`. Never the link.',
  'artifact.share_revoked': 'A share of an artifact was revoked (issue #624): the user no longer sees it, or the link stops working at once.',
  'artifact.removed': 'An artifact was removed, with its shares (issue #624): by a person or its job (`removed`, `by`), or by the retention in Settings → Artifacts (`retention`), or merged into another artifact, which holds its revisions now (`merged`, `into`, issue #687).',
  'artifact.revised': 'An artifact has a new latest revision (issue #675): a job put a file to it (`by` the job), or a person restored an older revision (`restoredFrom`), which is copied, not moved; or a person revised it with a file or another artifact\'s latest content (`copiedFrom`), or merged another artifact into it, whose revisions are added oldest first, each still `by` the job that made it (`mergedFrom`, issue #687). Its id, its links and its shares stay. `note`: what changed, in one line. The older revisions stay readable.',
  'artifact.revision_pinned': 'A person pinned an artifact\'s revision, so the retention sweep keeps it and its artifact, or unpinned it (issue #675).',
  'artifact.revision_removed': 'The retention sweep removed an older revision of an artifact, not pinned, made longer ago than the user keeps artifacts (issue #675). The latest revision is never removed this way.',
  'artifact.posted': 'A job shared an artifact with its owner, who sees it already (issue #673): its link was posted on the job\'s issue as the job\'s comment (`comment`, its URL), or could not be (`error`), or the job has no issue (`issue: false`). Also on the job\'s stream.',
  'artifact.settings_changed': 'Settings → Artifacts changed (issue #624): the size limits per artifact and per user, the retention, whether public links work and for how long, and the link base (issue #673).',
  'item.snapshot_recorded': 'An item\'s approved text was recorded (issue #662): its title, body and the assignee comments its job runs, by their SHA-256 `hash`. `reason`: at its first job (`intake`), from its first job by the migration (`backfill`), or a person accepted new text (`accepted`). Never the text.',
  'item.changed_since_snapshot': 'A job was held because its item\'s text changed since the snapshot (issue #662): at Run again, an assessor or problem-release rerun, a rediscovered item, or while it waited. `editors`: who edited the title or body since, from the timeline; `newComments`: how many assignee comments are new. Never the text.',
  'item.original_kept': 'A person kept the original text of a changed item (Rerun the original, issue #662): the job runs the snapshot\'s text, and that live text holds it no more.',
  'item.new_text_accepted': 'The owner accepted an item\'s new text (issue #662), allowed by Access: the job runs it, and it is the item\'s new snapshot. The hashes before and after, and who edited it.', 'item.edit_seen': 'A sync saw the item of a started job edited (issue #2775 part 3; issue #655 part 7): its title or body is not the text the job last saw. `fromHash`: that text\'s SHA-256, `toHash` the live text\'s; `editors`: who edited it, from the timeline. Once per new text. The job goes on with the text it started with, and is told nothing; its kept delivery track records it as a text edit, at the step it is in. Never the text.',
  'lanes.recommended': 'A machine\'s lane recommendation changed (issue #688): the `lanes` it can run, from its resource history (`headroom`, the most lanes it ran without resource pressure or slow progress, and what each lane\'s cost leaves room for) and the usage it burns (`usage`: `free`, `near` the soft limit, past the `soft` limit, at the `hard` limit), within its bounds, next to the `configured` lanes the decider uses. `reason` in plain words; `confidence` 0..1 from the history it stands on. Recorded, not applied: an admin applies it. Recorded when the recommended or the configured lanes change. `mode` (`shadow`) only in one recorded while active mode was there. `decidedBy: jev`: the lanes are Jev\'s applied pick at the `lane-count` decision point (issue #550), and `rules` the rules\' own recommendation.',
  'lanes.tuning_changed': 'An admin changed a machine\'s lane tuning settings (issue #688): auto-tune on or off, and the least and most lanes a recommendation may name. `from` and `to`, and `by`. `mode` (`shadow`, `active`) only in a change saved while active mode was there.',
  'lanes.applied': 'An admin applied a machine\'s lane recommendation (issue #688): its configured lanes went `from` → `to`, set as an edit of the machine sets them. `reason` in plain words, `confidence` 0..1 from the history it stands on, `by`: who. An admin can undo it. Without `by` (and with `configured`): the hopper applied it itself in active mode, before each one was an admin\'s.',
  'lanes.undone': 'An admin undid the last lane recommendation applied to a machine (issue #688): its configured lanes went back `from` → `to`. `by`: who.',
  'lanes.dismissed': 'An admin dismissed a machine\'s lane recommendation (issue #688): the `lanes` it recommended at the `configured` lanes, and why (`reason`). Not offered again until the recommendation or the configured lanes move. `by`: who.',
  'bug_report.filed': 'A person filed a bug report with Report a bug (issue #694), through their own GitHub connection, on the hopper\'s own repository `repo`: a new issue labelled `user-report` (`kind: issue`), or a comment on a similar open one (`kind: comment`). Its `number` and `url`, the `jobId` it was about, and `by`. `fromJob`: a running job filed it about itself through the hopper (`hopper-gh report bug`), with its user\'s connection; `by` is then `job <id>`. `later`: a report kept while GitHub could not take it (`bug_report.kept`), sent now; `id` is its report. Never its text.',
  'bug_report.kept': 'A bug report was kept to send later (issue #694): no GitHub connection, or GitHub could not take it now (no answer, no access to the repository, a rate limit, its own failure). `problem` says why; `id` is the report in Your reports. The hopper sends it later (`bug_report.filed` with `later`). `jobId`, `by` and `fromJob` as in `bug_report.filed`. Never its text.',
  'bug_report.failed': 'A bug report was not filed (issue #694): GitHub refused it for good. `error` says why; `jobId`, `by` and `fromJob` as in `bug_report.filed`.',
  'repo_checks.job_queued': 'A person queued the "Add PR checks to <repo>" job for job repository `repo` (`owner/repo`, lowercased), which has no checks (issue #677): an issue filed through their own GitHub connection with the hopper label, assigned to their connected account, so a job source takes it. `existing`: an open issue of that title was there, and none was filed. Its `number` and `url`, and `by`.',
  'repo_checks.dismissed': 'A person dismissed (`dismissed: true`) or brought back (`false`) the "Add PR checks" recommendation for job repository `repo` (`owner/repo`, lowercased; issue #677). The "no checks" warning stays. `by` who did it.', 'job.sub_issue_linked': 'The hopper linked a job\'s required child as a GitHub sub-issue of its parent at a later try (issue #1607): GitHub refused the link, or did not answer, as the child was filed (`job.child_issue_filed` with `subIssue: false`). The hopper keeps such a link and tries it again until it is made. `requestId` names the request that filed the child; `parent` and `child` as there.',
  'job.child_issue_filed': 'A running job filed an issue through the hopper (issue #729, issue lineage): `child`, a child of the job\'s own issue `parent` (each `repo` and `number`; the child\'s `url`). `required`: the job marked it a required child (`--required`), and the hopper linked it as a GitHub sub-issue of the parent, so the parent is not done while it is open (`subIssue`; `false` with `subIssueError` when GitHub refused the link: the issue is filed all the same). Else a follow-up: the issue\'s text names its parent, and nothing waits on it. `routed` (issue #1510): the hopper labelled the required child with the job sources\' label and assigned it to the job\'s user, so Intake lists it as a request card. `unassigned` (issue #1856): the assignees GitHub did not set on it, though the hopper asked twice (GitHub drops an assignee it cannot set with no error): the issue keeps its label and waits as not assigned until a person assigns it. `requestId` names the request, as in `github_proxy.done`.',
  'direct_job.submitted': 'A person submitted a direct job (issue #901): `id` the direct job, `by` who and `via` the way (`ui`, `api` for an API token, `cli`), its routing `labels`, the `authorizations` they gave it, and `repo` when its work may open a pull request there, and `pushRequirements` the ids of its own push requirements when it has some (issue #2555 part 3). Its job is queued in the same transaction (`job.queued`, source `direct`). Never its title or brief: those stay on the record.',
  'direct_job.promoted': 'A person promoted a direct job to GitHub (issue #946), with their own GitHub connection: `id` the direct job, `repo`, `kind` (`issue`: a new issue, or `comment` on the issue `number`), `number`, `url`, `by` who, `artifacts` how many were linked, and `update` true when it edited what an earlier promotion posted. Never the text.',
  'direct_job.promotion_revoked': 'A person revoked the promotion of a direct job (issue #946): `id`, `repo`, `kind`, `number`, `by`. The link in the hopper ends; GitHub keeps what was posted.', 'direct_query.accepted': 'A caller asked a direct query (issue #2184): `id` the query, `requestId` the caller\'s own id of it, `by` who and `via` the way, `callback` the webhook subscription its callback goes to. Its job is queued in the same transaction (`job.queued`, source `direct`). Never the question: it stays on the record. Delivered to the `callback` subscription too, whatever events it lists.', 'direct_query.answered': 'A direct query\'s job finished (issue #2184): `answer` its result, `artifacts` its evidence kept in the hopper (links need a hopper sign-in), `url` the query in the hopper. Delivered to the `callback` subscription too, whatever events it lists: that delivery is the callback.', 'direct_query.failed': 'A direct query\'s job failed or was turned away (issue #2184): `error` why — for a question whose answer needs a change, what a person must file as an issue. Delivered to the `callback` subscription too.', 'direct_query.cancelled': 'A direct query\'s job was cancelled (issue #2184). Delivered to the `callback` subscription too.', 'direct_query.question_asked': 'A direct query\'s job asked a question that reached a person (issue #2184, part 2): once per question, with its `question.escalated_to_human`. `questionId`, `question` (the text, masked), `answerUrl` (where a person answers it in the UI). The caller answers it with `POST /ui/api/questions/:id/answer`, as a person does in Questions. Delivered to the `callback` subscription too.',
  'pointed_job.created': 'A person made a pointed job through the API (issue #425): `id`, on the issue or pull request `pointer` (`kind`, `number`, `url`) of the GitHub repository `repo`; `source` what made it (`api`), `by` who. It starts `queued`. Never its directive.',
  'github_watch.changed': 'A GitHub watch saw its pointed job\'s item change (issue #427): one event per poll that found a change, with every change of that poll in `changes` — `state` (`from`, `to`: `open`, `closed` or `merged`; `reason` GitHub\'s state reason; `mergedAt`), `labels` (`added`, `removed`), `comments` (`added`: `id`, `author`, `at`; `removed`: how many went), `reviews` (`added`: `id`, `author`, `state`, `at`), `linkedPullRequests` (`added`, `removed`, by URL). `pointedJob`, `repo`, `pointer`: what is watched. A job on a question posted on its issue thread is watched too (issue #435): then `pointedJob` is the job\'s id, and the event carries `jobId`, on the job\'s timeline. A poll that sees no change, and the first poll of a watch, record nothing. Never a comment\'s text.',
  'drift.found': 'A component watcher (issue #1077) found a kind of drift that was not there at its check before: `watcher` (`ledger-github`: the work-item ledger against GitHub), `kind` (`failed_but_finished`, `pr_open_but_ended`, `pull_request_state`, `issue_state`) and how many `items` are in it. Never an item\'s key.',
  'drift.cleared': 'A kind of drift a component watcher found before is gone at its check (issue #1077): `watcher` and `kind`. Its drift issue, if it has one, is updated to say so.',
  'drift.issue_filed': 'A component watcher filed a drift issue on the hopper\'s own repository with the user\'s GitHub connection (issue #1077), the user\'s setting on: `watcher`, `kind`, the issue\'s `number` and `url`. One per kind of drift: the next check finds it by its drift key.',
  'drift.issue_updated': 'A component watcher updated the drift issue of a kind of drift (issue #1077), found by its drift key: what it lists changed, or the drift is gone. Fields as `drift.issue_filed`.',
  'component_watchers.settings_changed': 'An admin changed whether the component watchers file drift issues (issue #1077): `from` and `to`, each `fileIssues`. Applies at the next check.',
  'github_watch.settings_changed': 'A person changed how often the GitHub watches poll (issue #427): `from` and `to`, each `intervalSeconds`. The rounds start again at once on the new interval, with no restart.',
  'infra.plan_recorded': 'A job recorded a plan of an infrastructure change (issue #870): what made it (`tool`), the asset an apply of it is minted a credential for, the workspace or app it changes (`target`), the repository, branch (`ref`) and commit it was made at, its pull request, the read profile it was made with (`read`), the job\'s issue, whether a saved plan file came with it (`file`), when it goes stale (`expiresAt`), and its `summary` (issue #870 part 2): what it changes in plain words, its `level` (`low` or `high`), its risk callouts (`destroy`, `iam`, `prod`, `data`, `network`), and whether it `failed` a check (a new AWS resource without the MAP tag: nobody approves such a plan). Never its text or its file. A plan is never changed once kept. The notifiers send it, with the watchers of its environments (part 4).',
  'infra.plan_approved': 'A plan of an infrastructure change was approved (issue #870), on Infra: until the plan is stale, an apply that names it, made at the commit its branch is at, is minted the credential it asks. By risk (part 3): an operator or an admin approves a low-risk plan in uat only, an admin any other. `by`, who; `auto` when the hopper approved it itself, as the plan was kept, with auto-approve on; `level`, the plan\'s risk level, when it has a summary. On the timeline of the job that recorded the plan. The notifiers send it, with the watchers of the plan\'s environments (part 4).', 'infra.plan_rejected': 'A person rejected a plan of an infrastructure change (issue #2368), on Infra or with `hopper infra reject`: it is never approved after, and the vault mints nothing for an apply that names it. `by`, who; `note`, why. A job that waits on the plan is woken, told who rejected it and the note. On the timeline of the job that recorded it.',
  'infra.settings_changed': 'An admin turned auto-approve of infra plans on or off (issue #870 part 3): on, the hopper approves a low-risk plan in uat only when a job records it. `from` and `to` (`autoApprove`), and `by`, who. It applies to the next plan kept.', 'infra.applies_changed': 'The hopper\'s admin turned infra applies on or off (issue #1722): off, the vault mints only read credentials, and no need or box step that applies runs; an infrastructure change goes through CI. `on`, the new setting; `by`, who. It applies to the next mint and the next step. An instance event: in every user\'s log.',
  'infra.watchers_changed': 'An admin named the environment watchers (issue #870 part 4): who is told of each plan, approval and apply, by the environments the plan names (`prod`, `uat`, `staging`, `dev`, `qa`), and of every plan (`*`). Names as the notifier\'s receiver knows them. `from` and `to` are the whole lists; `by`, who.',
  'api_grant.minted': 'A person minted a grant for an agent (issue #881): its id, `label`, `holder`, `role`, `scopes`, whether its tokens are box tokens (`box`), its fixed end (`endsAt`, null: none) and how long its API tokens live (`tokenMinutes`). Never a token.',
  'api_grant.refreshed': 'An agent traded a grant\'s refresh token for a new API token and a new refresh token (issue #881): `from` is the caller, as the sign-in limit counts it. Never a token.',
  'api_grant.reuse_detected': 'A refresh token already spent was sent again after the grace period (issue #881): it may be stolen, so the grant was revoked at once (`api_grant.revoked`, reason `reuse-detected`). `from`: who sent it. Subscribe a notifier to this to be told.',
  'api_grant.revoked': 'A grant ended, and every API token of it (issue #881). `reason`: `revoked` (a person revoked it), `revoked-all` (a person revoked every grant), `reuse-detected` (a spent refresh token sent again), `expired-idle` (no refresh for 30 days), `expired-absolute` (its fixed end passed), `realm-changed` (its minter\'s sign-in grants no role any more), or `refused` (Access refused it at its mint).',
  'api_tokens.settings_changed': 'The hopper\'s admin changed how long an API token lives (issue #881): `tokenMinutes`. API tokens issued after it live that long; those there are keep their own ends. In the admin\'s log.',
  'step.started': 'A running job\'s sandbox step started on its Windows host (issue #731), or in a box its own sandbox request started (issue #1004), or in a one-shot need box of a `template`, with the `needs` the vault minted its credentials for (issue #1007): `step` its id, the `host` or the `box`, its `command` (at most 300 characters), its timeout, the size of the inputs it sent and the `outputs` it asked back; `secrets`: the names of the vault secrets it was given (a Windows step; a box step, issue #1875). Never its output.',
  ...LANDING_BATCH_DOCS, ...MACHINE_DISK_EVENT_DOCS, ...MACHINE_DRAIN_EVENT_DOCS, ...SANDBOX_HOST_EVENT_DOCS, ...STEP_SCHEDULE_EVENT_DOCS, ...TERMINAL_EVENT_DOCS, ...CHANGE_KIND_EVENT_DOCS, ...KEPT_WORK_EVENT_DOCS, ...GIVE_BACK_EVENT_DOCS, ...PREEMPTION_EVENT_DOCS, ...SKILL_LIBRARY_EVENT_DOCS, ...GITLAB_EVENT_DOCS, ...ISSUE_DRAFT_EVENT_DOCS,
  'step.finished': 'A sandbox step ended, on its Windows host (issue #731) or in its box (issue #1004; a need box, issue #1007): its `exit` code and how long it ran; `outputsBytes` when its outputs came back, and `outputsSha256`, their sha256 as a need box made it and the hopper checked it on arrival (issue #2288); `problem` when the hopper could not run it, stopped it (its timeout, or the job stopped waiting) or could not bring its outputs back, or its outputs held a vault secret\'s value and were not given (a box step, issue #1875).',
  'step.refused': 'A running job asked for a sandbox step and was told no (issues #731, #1004, #1007), with `reason`: for a need step, a need the vault minted no credential for (`box`: the need box), or no container runtime; no such Windows host, no such box of the job\'s, a `--secret` for a box, a bad command, timeout or output, inputs too large, a secret the host does not give, or a vault secret the vault refused.',
  'vault.step_delivered': 'A vault secret was given to a running job\'s Windows sandbox step (issue #731): on the step\'s ssh connection to the Windows `host`, into the step\'s environment only, never to the job, a file or an argument. Or to its box step (issue #1875): `host` the need box, the secret copied into it as a file, never into its environment or to the job. The secret\'s name, the host and the job; never the value. `backend`: the vault backend it was read from, when it is kept in one.',
  'vault.step_refused': 'A running job\'s Windows sandbox step, or its box step (`host` the need box, issue #1875), asked for a vault secret and the vault refused (issue #731): the job has no vault grant (a grant ask is opened), it is not at work, the vault holds no such secret, it is a minting credential, or it cannot be opened or read. `reason` says which; never a value.',
  'infra.out_of_band_recorded': 'A read-only check — a job\'s, or an outside collector\'s with an API token (part 2) — reported an infrastructure change that did not come through IaC or GitOps (issue #871): drift (`gitops`: an app out of sync; `terraform-plan`: a non-empty plan on unchanged code) or an audit-log write (`cloudtrail`, `kube-audit`) by a principal that is no controller identity and no plan-bound apply credential. What changed (`target`), the action in the source\'s words (`what`), who (`who`), when (`at`), the signal\'s own id (`key`), and who reported it: the job whose check did and its issue, or the collector (`reporter`, its API token\'s label), then on no job\'s timeline. Never the signal\'s detail. On Infra until a person marks it; the notifiers send it.',
  'infra.out_of_band_marked': 'A person marked an out-of-band change on Infra (issue #871): `adopted` (brought back into git), `reverted`, or `accepted` with its `reason`. Tracking only: the hopper reverts nothing. On the timeline of the job whose check reported the change.',
  'approval.confirmation_asked': 'An API token asked to approve a high-risk infra plan or a write, sync or apply profile of a template (issue #909), and the hopper did not approve it: a person confirms it by approving the item in the UI. `kind` (`infra-plan`, `vault-profile`), `ref` the item, `words` what to approve, `asker` the API token\'s label. Sent at most once an hour for an item; subscribe a webhook to it to be told. On the timeline of the job that recorded the plan.',
  'infra.topology_reported': 'A read-only check, or the hopper\'s own topology discovery (part 3), reported topology sources (issue #1781, design.md "The infrastructure topology"): for each source (`key`: `aws/<account>/<region>` or `kubernetes/<cluster>`), `ok` and the `nodes` and `links` it found, or the `error` that kept it from being read; a failed source keeps its last good snapshot. `reporter`: the API token\'s label, else who signed in, or `topology discovery`. Never a node. On no job\'s timeline.', 'infra.controllers_changed': 'An admin changed the controller identities (issue #871): the principals whose writes are GitOps\'s, not out of band. A trailing `*` names a group. `from` and `to` are the whole lists.',
  'pointed_job.status_changed': 'A pointed job moved from status `from` to `to` (issue #425), along the allowed transitions: queued → running | abandoned; running → awaiting_review | queued | abandoned; awaiting_review → merged | running | abandoned. `lane`: the lane that works it, when it moved to running. `by` who moved it. A refused move records nothing.',
};

type Prop = Record<string, unknown>;

function typeOf(p: Prop): string {
  if (Array.isArray(p.enum)) return p.enum.map((v) => `\`${String(v)}\``).join(' \\| ');
  if (Array.isArray(p.anyOf)) return (p.anyOf as Prop[]).map(typeOf).join(' \\| ');
  if (p.type === 'array') return `${typeOf((p.items ?? {}) as Prop)}[]`;
  if (typeof p.type === 'string') return p.type;
  return 'any';
}

function fieldRows(schema: Prop): string {
  const props = (schema.properties ?? {}) as Record<string, Prop>;
  const required = new Set((schema.required ?? []) as string[]);
  const rows = Object.entries(props).map(([k, p]) => `| \`${k}\` | ${typeOf(p)} | ${required.has(k) ? 'yes' : 'no'} |`);
  return rows.length ? ['| field | type | required |', '|---|---|---|', ...rows].join('\n') : '`data` is `{}`.';
}

export function renderEventsMarkdown(): string {
  const files = exportJsonSchemas();
  const out = [
    '# Events',
    '',
    '<!-- generated by `npm run schemas` from src/events — do not edit -->',
    '',
    'Every event (stored, SSE, `/api/events`, webhook body) is the envelope below. `schemaVersion` is the',
    "version of **that type's** payload schema; the JSON Schema for each is in `docs/schemas/<type>.v<N>.json`.",
    'An additive (optional) field keeps the version; a removed, renamed or retyped field bumps it and adds',
    '`<type>.v<N+1>.json` — the old file stays as documentation of what older consumers received.',
    '',
    'Events stored before phase 3 read as v1 and are not re-validated.',
    '',
    `Stored events are never rewritten. Superseded versions stay readable and documented: ${Object.keys(LEGACY_EVENT_SCHEMAS).map((k) => `\`${k}\``).join(', ')}`,
    '(phase 5 renamed Jev → router: `jev.mode_changed` became `router.mode_changed`; slice 2 made question',
    'stages instance names: `question.escalated.target` and `question.answered.by` were `opus | fable | human` in v1;',
    'issue #211 removed the router mode: `router.mode_changed` is retired, and v3 of `job.prioritized` and',
    '`decision.made` carry no `mode` / `routerMode`).',
    '',
    '```json',
    '{ "schemaVersion": 1, "seq": 1, "id": "uuid", "type": "job.queued", "at": "ISO",',
    '  "jobId": "…", "laneId": "…", "machineId": "…", "decisionId": "…", "questionId": "…", "data": { … } }',
    '```',
    '',
    'Schema: `docs/schemas/envelope.v1.json`. Payloads are strict: unknown keys are rejected.',
    '',
    'Every `question.*` event names the **raising machine** — the machine the question was asked on — as the',
    '`machineId` subject (and `laneId`, where the lane is known) and as `raisedBy` (`machineId`, `name`, `laneId`)',
    'in its data: a snapshot taken when the question was asked, so it stays right after the job moves or the',
    'machine is renamed or removed. Absent on a question asked before it was recorded, with nothing to fill it from.',
  ];
  for (const t of EVENT_TYPES) {
    const v = EVENT_SCHEMA_VERSIONS[t];
    out.push('', `## \`${t}\``, '', `Version ${v} (\`docs/schemas/${t}.v${v}.json\`). ${EVENT_DOCS[t]}`, '',
      fieldRows(files[`${t}.v${v}.json`] as Prop), '', '```json', JSON.stringify(EVENT_EXAMPLES[t], null, 2), '```');
  }
  return `${out.join('\n')}\n`;
}
